import React from 'react';
import { Stack, Typography } from "@mui/material";
import UIText from '../../../utilities/textResource';

const NotFound: React.FC = () => {
    return (
        <>
            <Stack
                sx={{
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: 'center',
                    alignItems: 'center',
                    gap: 2,
                    marginTop: "40px"
                }}
            >
                <img src="https://codewithabubakr.github.io/Scaleflex-Add-in/assets/empty_folder.png" height={120} width={120} alt="Empty Folder" />
                <Typography sx={{ marginTop: 2, fontSize: "16px", fontWeight: "bold", color: "#3d3d3d" }}>
                    {UIText.tabs.not_found}
                </Typography>
            </Stack>
        </>
    );
};

export default NotFound;