import React, { useState } from 'react';
import { Box, Button, IconButton, Stack, TextField, Tooltip, Typography } from '@mui/material';
import UIText from '../../../utilities/textResource';
import { useNavigate } from 'react-router-dom';
import Loader from '../../loader/loader';
import Toast from '../../toast/Toast';
import { auth } from '../../../auth/auth';
import { IoMdArrowRoundBack } from 'react-icons/io';
import TokenAccessDialog from './tokenAccessDialog';
import VerificationDialog from './VerificationDialog';
import { useData } from '../../../hook/DataContext';
import { Company } from '../../../utilities/types';

const EmailPassword: React.FC = () => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [password, setPassword] = useState('');
    const [email, setEmail] = useState('');
    const [MFA_UUID, setMFA_UUID] = useState('');
    const [error, setError] = useState('');
    const [redirectUrl, setRedirectUrl] = useState("");
    const [userEmail, setUserEmail] = useState("");
    const { companies, setCompanies } = useData();
    const [errors, setErrors] = useState({ password: '', email: '' });
    const [tokenAccessDialogOpen, setTokenAccessDialogOpen] = useState(false);
    const [isVerificationDialogOpen, setIsVerificationDialogOpen] = useState(false);

    const handleBackToHome = () => {
        navigate("/");
    };

    const handleLoginButton = () => {
        setError(null);

        // Check for input validation
        const newErrors = {
            password: password.trim() === '' ? 'Password is required' : '',
            email: email.trim() === '' ? 'Email is required' : '',
        };

        setErrors(newErrors);
        if (password && email) {
            const loginData = {
                userName: password,
                password: email
            }

            if (loginData) {
                setIsLoading(true);
                // Call the API to authenticate the user
                auth(email, password, async (error, data) => {
                    if (error) {
                        console.log("Authentication failed", error);
                        if ((error as any)?.status === "pending") {
                            setIsVerificationDialogOpen(true);
                            setMFA_UUID((error as any).mfa_uuid);
                        } else {
                            setError((error as any).msg);
                            console.log((error as any).msg);
                        }
                        setIsLoading(false);
                    } else if (data) {
                        console.log("Authentication success", data);
                        setRedirectUrl(data.redirect_to);
                        setUserEmail(data.user_email)
                        setCompanies(data.companies || []);
                        setTokenAccessDialogOpen(true);
                        setIsLoading(false);
                    }
                });
            }
        }
    };

    const handleTokenAccessDialogConfirm = (companies: Company[]) => {
        // Assuming the first company is selected; adjust logic as needed
        const selectedCompany = companies[0];
        if (selectedCompany) {
            console.log("selected company", selectedCompany);
            localStorage.setItem("x-company-token", selectedCompany.uuid);
        }

        navigate(redirectUrl);
        setTokenAccessDialogOpen(false);
    };

    const handleLoginAnotherAccount = () => {
        setTokenAccessDialogOpen(false);
        setEmail('');
        setPassword('');

        localStorage.removeItem("username");
        localStorage.removeItem("x-company-token");
        localStorage.removeItem('session_uuid');
        localStorage.removeItem("expires_x_session_token");
        navigate('/email-password');
    }

    const handleCloseTokenAccessDialog = () => {
        setTokenAccessDialogOpen(false);

        localStorage.removeItem("username");
        localStorage.removeItem("x-company-token");
        localStorage.removeItem('session_uuid');
        localStorage.removeItem("expires_x_session_token");
        navigate('/email-password');
    }

    const handleInputChange = (field: string, value: string) => {
        if (field === 'password') {
            setPassword(value);
            if (errors.password) setErrors((prev) => ({ ...prev, userName: '' }));
        } else if (field === 'email') {
            setEmail(value);
            localStorage.setItem("username", value);
            if (errors.email) setErrors((prev) => ({ ...prev, email: '' }));
        }
    };

    return (
        <>
            {isLoading && (
                <Loader
                    loaderOverlay={{
                        position: 'fixed',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: '100%',
                        backgroundColor: 'rgba(255, 255, 255, 0.8)',
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        zIndex: 9999,
                    }}
                    loader={{ size: "40px", color: "#1976D2" }}
                />
            )}

            <Tooltip title="Back to Home" placement="left-start">
                <IconButton
                    edge="end"
                    color="inherit"
                    aria-label="back to dashboard"
                    onClick={handleBackToHome}
                    sx={{ fontSize: "20px", marginLeft: "6px", marginTop: "6px" }}
                >
                    <IoMdArrowRoundBack />
                </IconButton>
            </Tooltip>

            <Typography
                sx={{
                    fontWeight: "bold",
                    fontSize: "26px",
                    textAlign: "center",
                    paddingTop: "40px"
                }}
            >
                {UIText.login.scaleflex}
            </Typography>

            <Typography
                sx={{
                    fontSize: "16px",
                    paddingTop: "2px",
                    color: "#5F5F5F",
                    textAlign: "center",
                }}
            >
                {UIText.login.description}
            </Typography>

            <Box sx={{ margin: "30px 12px 20px 12px" }}>
                <TextField
                    label={UIText.login.email}
                    variant="outlined"
                    size="small"
                    type="email"
                    value={email}
                    onChange={(e) => handleInputChange('email', e.target.value)}
                    error={!!errors.email}
                    helperText={errors.email}
                    sx={{
                        width: "100%",
                        maxWidth: "600px",
                    }}
                />
                <TextField
                    label={UIText.login.password}
                    variant="outlined"
                    size="small"
                    type="password"
                    value={password}
                    onChange={(e) => handleInputChange('password', e.target.value)}
                    error={!!errors.password}
                    helperText={errors.password}
                    sx={{
                        width: "100%",
                        maxWidth: "600px",
                        marginTop: "16px",
                    }}
                />
            </Box>

            <Stack sx={{ margin: "12px 12px" }}>
                <Button
                    variant="contained"
                    sx={{
                        color: "#fff",
                        fontWeight: 600,
                        textTransform: "capitalize",
                    }}
                    onClick={handleLoginButton}
                >
                    {UIText.login.login}
                </Button>
            </Stack>

            {/* open token access dialog */}
            {tokenAccessDialogOpen && (
                <TokenAccessDialog
                    open={tokenAccessDialogOpen}
                    email={userEmail}
                    companies={companies}
                    onClose={handleCloseTokenAccessDialog}
                    onConfirm={handleTokenAccessDialogConfirm}
                    onLoginAnotherAccount={handleLoginAnotherAccount}
                />
            )}

            {/* open verification code dialog */}
            {isVerificationDialogOpen && MFA_UUID && <VerificationDialog mfa_uuid={MFA_UUID} />}
            {error && (<Toast error={error} />)}
        </>
    );
};

export default EmailPassword;