export const getAssetsSortBy = async (
  x_filerobot_key: string,
  user_name: string,
  pageName: string,
  displayName: string,
  sortField: string,
  sortDirection: string,
  offset: number = 0,
  limit: number = 20,
  callback: (error: Error | null, data: any | null) => void
): Promise<void> => {
  try {
    if (!process.env.API_BASE_URL) throw new Error("API_BASE_URL is not defined");

    let url: string | URL | Request;
    if (pageName !== "home-page" && pageName === "folders-assets") {
      url = `${process.env.API_BASE_URL}/${user_name}/v5/files` +
        `?preview=2301` +
        `&folder=${displayName}` +
        `&recursive=0` +
        `&sort=${sortField}:${sortDirection}` +
        `&offset=${offset}` +
        `&limit=${limit}`;
    } else {
      url = `${process.env.API_BASE_URL}/${user_name}/v5/files` +
        `?preview=2301` +
        `&folder=%2F` +
        `&recursive=1` +
        `&sort=${sortField}:${sortDirection}` +
        `&offset=${offset}` +
        `&limit=${limit}`;
    }

    console.log("Fetching all assets with sort:", url);

    const myHeaders = new Headers();
    myHeaders.append("Content-Type", "application/json");
    myHeaders.append("X-Filerobot-Key", x_filerobot_key);

    const response = await fetch(url, { method: "GET", headers: myHeaders });
    const result = await response.json();

    if (result.status === "success") callback(null, result);
    else callback(new Error("API responded but status not success"), null);

  } catch (error: any) {
    console.error("Fetch error:", error);
    callback(error, null);
  }
};

