export const auth = async (email: string, password: string, callback: (error: Error | null, data: any | null) => void): Promise<void> => {
    const myHeaders = new Headers();
    myHeaders.append("Content-Type", "application/json");
    myHeaders.append("Origin", "https://hub.filerobot.com");
    myHeaders.append("Pragma", "no-cache");
    myHeaders.append("Referer", "https://hub.filerobot.com/login");
    myHeaders.append("X-Company-Token", "d634a705-2d40-4e484c");
    myHeaders.append("X-Project-Token", "afbd85fc-9121-44c52e538e");
    myHeaders.append("X-Session-Token", "undefined");
    myHeaders.append("X-Version", "2018_R2");

    const raw = JSON.stringify({
        "login": {
            "email": email,
            "password": password
        }
    });

    const requestOptions = {
        method: "POST",
        headers: myHeaders,
        body: raw
    };

    fetch(`${process.env.AUTH_BASE_URL}/api/login`, requestOptions)
        .then((response) => response.json())
        .then((result) => {
            console.log(result);

            if (result && result.status === "success") {
                localStorage.setItem("session_uuid", result.session_uuid);
                localStorage.setItem("expires_x_session_token", result.api_info.timestamp);
                callback(null, result);
            } else {
                console.error("Authentication failed: ", result.msg);
                callback(result, null);
            }
        })
        .catch((error) => {
            console.error(error);
            callback(error, null);
        });
};