import React, { useState, useEffect } from 'react';
import { Box } from '@mui/material';
import { refreshSASSKey } from '../../../auth/renewSASSKey';
import { useLocation } from 'react-router-dom';
import Loading from '../../loader/loading';
import TabsPage from '../tabs/page';
import Search from './search';
import { getSAASKey } from '../../../auth/getSASSKey';
import { refreshXSessionToken } from '../../../auth/renewXSessionToken';
import { getProjectToken } from '../../../services/projects';
import { getFoldersList } from '../../../services/folders/getFoldersList';
import { getAllAssetsList } from '../../../services/getAllAssetsList/getAllAssetsList';
import { AssetDetail } from '../../../utilities/types';
import { useData } from '../../../hook/DataContext';
import Header from '../header';

const Home: React.FC = () => {
    const location = useLocation();
    const [isLoading, setIsLoading] = useState(false);
    let defaultTab = location.state?.defaultTab ?? 0;
    const { allFolders, setAllFolders, allAssetUrls, setAllAssetUrls, setAllAssetDetails, setAllRootDirAssetDetails } = useData();

    // Get values from localStorage
    let x_project_token: string;
    const user_name = localStorage.getItem("user-name");
    const X_SAAS_Key = localStorage.getItem("X_SAAS_Key");
    const x_session_token = localStorage.getItem('session_uuid');
    const x_company_token = localStorage.getItem("x-company-token");
    const expires_X_SAAS_Key = localStorage.getItem("expires_X_SAAS_Key");
    const expires_x_session_token = localStorage.getItem("expires_x_session_token");

    // Check refresh SASS Key on component mount
    useEffect(() => {
        if (allFolders.length > 0 && allAssetUrls.length > 0) {
            console.log("Using cached data");
            return;
        }
        const fetchData = async () => {
            setIsLoading(true);

            try {
                if (x_session_token && expires_x_session_token) {
                    // Check refreshXSessionToken is expire or not if refreshXSessionToken is expire then call API
                    await new Promise((resolve, reject) => {
                        refreshXSessionToken(x_session_token, expires_x_session_token, (error, data, notExpireXSessionToken) => {
                            if (error) {
                                if (error !== "refreshXSessionToken not expired yet") {
                                    console.log("refreshXSessionToken error:", error);
                                    reject(error);
                                } else {
                                    console.log("refreshXSessionToken not expired:", notExpireXSessionToken);
                                    resolve(notExpireXSessionToken);
                                }
                            } else {
                                console.log("refreshXSessionToken Success Callback", data);
                                resolve(data);
                            }
                        });
                    });
                }

                if (x_company_token && x_session_token) {
                    await new Promise((resolve, reject) => {
                        getProjectToken(x_company_token, x_session_token, (error, data) => {
                            if (error) {
                                console.log("getProjectToken error callback:", error);
                                reject(error);
                            } else {
                                console.log("getProjectToken success callback", data);
                                x_project_token = localStorage.getItem("x-project-token");
                                resolve(data);
                            }
                        });
                    });
                }

                if (!X_SAAS_Key && x_session_token && x_project_token) {
                    await new Promise((resolve, reject) => {
                        getSAASKey(x_session_token, x_project_token, x_company_token, (error, data) => {
                            if (error) {
                                console.log("getSAASKey error callback expired:", error);
                                reject(error);
                            } else {
                                console.log("getSAASKey success callback", data);
                                resolve(data);

                                const X_SAAS_Key = data.keychain.tokens.airstore_key
                                const user_name = data.project.name
                                getAllAssets(X_SAAS_Key, user_name);
                            }
                        });
                    });
                } else {
                    if (X_SAAS_Key && x_session_token && expires_X_SAAS_Key) {
                        await new Promise((resolve, reject) => {
                            refreshSASSKey(X_SAAS_Key, x_session_token, expires_X_SAAS_Key, user_name, (error, data, notExpireSASSKey) => {
                                if (error) {
                                    if (error !== "refreshSASSKey not expired yet") {
                                        console.log("refreshSASSKey error:", error);
                                        reject(error);
                                    } else {
                                        console.log("refreshSASSKey not expired:", notExpireSASSKey);
                                        resolve(notExpireSASSKey);

                                        getAllAssets(X_SAAS_Key, user_name);
                                    }
                                } else {
                                    console.log("refreshSASSKey Success Callback", data);
                                    resolve(data);

                                    const X_SAAS_Key = data.keychain.tokens.airstore_key
                                    const user_name = data.project.name
                                    getAllAssets(X_SAAS_Key, user_name);
                                }
                            });
                        });
                    }
                }
            } catch (err) {
                console.error("Error in async token flow:", err);
            } finally {
                setIsLoading(false);
            }
        };

        fetchData();
    }, []);

    const getAllAssets = async (X_SAAS_Key: string, user_name: string) => {
        if (X_SAAS_Key && user_name) {
            // Fetch folders
            await new Promise((resolve, reject) => {
                getFoldersList(X_SAAS_Key, user_name, (error, data) => {
                    if (error) {
                        console.error("getFoldersList error:", error);
                        reject(error);
                    } else {
                        console.log("getFoldersList success", data);
                        setAllFolders(data.folders || []);
                        resolve(data);
                    }
                });
            });

            // Fetch assets
            await new Promise((resolve, reject) => {
                getAllAssetsList(X_SAAS_Key, user_name, 1, (error, data) => {
                    if (error) {
                        console.error("getAssetsList error:", error);
                        reject(error);
                    } else {
                        console.log("getAssetsList success", data);

                        if (data?.files) {
                            // Extract thumbnails (existing code)
                            const urls = data.files?.map((file: any) =>
                                file.info?.thumbnail || file.info?.video_thumbnail || file.url.cdn
                            ).filter(Boolean) || [];

                            // Extract additional file details
                            const fileDetails: AssetDetail[] = data.files.map((file: any) => ({
                                name: file.name,
                                file_ext: file.info?.file_ext,
                                uuid: file.uuid,
                                size: file.size?.pretty,
                                type: file.type,
                                img_h: file.info.img_h,
                                img_w: file.info.img_w,
                                preview: file.info.preview,
                                thumbnail: file.info?.thumbnail
                                    ?? file.info?.video_gif
                                    ?? file.url.public,
                                url: file.url.path
                            }));

                            setAllAssetDetails(fileDetails);
                            setAllAssetUrls(urls);
                            console.log("AssetsView allAssetUrls:", urls);
                        }
                        resolve(data);
                    }
                });
            });

            await new Promise((resolve, reject) => {
                getAllAssetsList(X_SAAS_Key, user_name, 0, (error, data) => {
                    if (error) {
                        console.error("getAssetsList error:", error);
                        reject(error);
                    } else {
                        console.log("getAssetsList success", data);

                        if (data?.files) {
                            // Extract thumbnails (existing code)
                            const urls = data.files?.map((file: any) =>
                                file.info?.thumbnail || file.info?.video_thumbnail || file.url.cdn
                            ).filter(Boolean) || [];

                            // Extract additional file details
                            const fileDetails: AssetDetail[] = data.files.map((file: any) => ({
                                name: file.name,
                                file_ext: file.info?.file_ext,
                                uuid: file.uuid,
                                size: file.size?.pretty,
                                type: file.type,
                                img_h: file.info.img_h,
                                img_w: file.info.img_w,
                                preview: file.info.preview,
                                thumbnail: file.info?.thumbnail
                                    ?? file.info?.video_gif
                                    ?? file.url.public,
                                url: file.url.path
                            }));
                            setAllRootDirAssetDetails(fileDetails);
                            console.log("AssetsView allAssetUrls:", urls);
                        }
                        resolve(data);
                    }
                });
            });
        }
    }

    return (
        <>
            <Header />

            {/* Search Section */}
            <Search
                pageName="home-page"
                displayName='dashboard'
                onAssetsChange={setAllAssetUrls}
                onFoldersChange={setAllFolders}
            />

            {/* Tabs Section */}
            {isLoading ? (
                <Box sx={{ margin: 1 }}>
                    <Loading />
                </Box>
            ) : (
                <TabsPage
                    defaultTab={defaultTab}
                />
            )}
        </>
    );
};

export default Home;