import React, { useState, useEffect } from 'react';
import { Stack, Typography, IconButton, Box, Tooltip, ListItemIcon, ListItemText, ListItem, List, Button, TablePagination, TablePaginationProps } from "@mui/material";
import Header from '../../header';
import Search from '../../home/search';
import { FiArrowLeft, FiChevronLeft, FiChevronRight } from "react-icons/fi";
import { useLocation, useNavigate } from "react-router-dom";
import getFolderContents from '../../../../services/assets/getFolderContents';
import NotFound from '../notFound';
import { IoEyeOutline } from 'react-icons/io5';
import { MdOutlineWindow } from 'react-icons/md';
import { AssetDetail } from '../../../../utilities/types';
import { useData } from '../../../../hook/DataContext';
import { getAssetsSortBy, getSubFoldersSortBy } from '../../../../services/sortBy';
import { DEFAULT_PREVIEW, sortMap } from '../../../../utilities/allData';
import { IoMdArrowRoundBack } from 'react-icons/io';
import { getPreviewSrc } from '../../../../utilities/getPreviewSrc';

const FoldersAssets: React.FC = () => {
    const PAGE_SIZE = 50;
    const navigate = useNavigate();
    const location = useLocation();
    const [page, setPage] = useState(0);
    const [showAllFolders, setShowAllFolders] = useState(false);
    const handleFoldersToggle = () => setShowAllFolders((prev) => !prev);
    const { path, folderStack: incomingStack } = location.state || {};
    const [folderStack, setFolderStack] = useState<string[]>(() => {
        if (incomingStack && incomingStack.length > 0) {
            return incomingStack;
        }
        return path ? [path] : [];
    });
    const currentPath = folderStack[folderStack.length - 1] || "";
    const cleanedPath = currentPath.replace(/^\//, "");
    const displayName = cleanedPath.split("/").pop();
    const [allAssetUrls, setAllAssetUrls] = useState<string[]>([]);
    const [allSubAssetDetails, setAllSubAssetDetails] = useState<AssetDetail[]>([]);
    const user_name = localStorage.getItem("user-name");
    const currentSaasKey = localStorage.getItem("X_SAAS_Key");
    const visibleAssets = allAssetUrls.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
    const { folderCache, setFolderCache, allSubFoldersNames, setAllSubFoldersNames, sortValue, setSortValue, isLoading, setIsLoading } = useData();

    useEffect(() => {
        if (location.state?.page !== undefined) {
            setPage(location.state.page);
        }
    }, [location.state]);

    const handlePageChange = (
        _event: React.MouseEvent<HTMLButtonElement> | null,
        newPage: number
    ) => {
        setPage(newPage);
    };

    const handleBackToFirst = () => {
        setPage(0);
    };

    // Custom pagination actions component
    const CustomTablePaginationActions = ({
        count,
        page,
        rowsPerPage,
        onPageChange,
    }: Pick<
        TablePaginationProps,
        'count' | 'page' | 'rowsPerPage' | 'onPageChange'
    >) => {
        const handleBack = (event: React.MouseEvent<HTMLButtonElement>) => {
            onPageChange(event, page - 1);
        };

        const handleNext = (event: React.MouseEvent<HTMLButtonElement>) => {
            onPageChange(event, page + 1);
        };

        return (
            <>
                <Box sx={{ flexShrink: 0, display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    <IconButton
                        onClick={handleBack}
                        disabled={page === 0}
                        sx={{ p: 0.5, minWidth: 'auto' }}
                    >
                        <FiChevronLeft size={16} />
                    </IconButton>
                    <IconButton
                        onClick={handleNext}
                        disabled={page >= Math.ceil(count / rowsPerPage) - 1}
                        sx={{ p: 0.5, minWidth: 'auto' }}
                    >
                        <FiChevronRight size={16} />
                    </IconButton>
                </Box>
            </>
        );
    };

    useEffect(() => {
        if (!currentSaasKey || !user_name || !path) return;

        if (folderStack.length === 0 && path) {
            setFolderStack([path]);
        }

        const currentFolder = folderStack[folderStack.length - 1] || path;
        const cacheKey = `${user_name}:${currentFolder}`;

        if (folderCache[cacheKey]) {
            const cached = folderCache[cacheKey];
            setAllSubFoldersNames(cached.folders);
            setAllSubAssetDetails(cached.files);
            setAllAssetUrls(cached.urls);
            return;
        }

        const handleFolderFetch = async (X_SAAS_Key: string, user_name: string, displayName: string, onFoldersChange: (folders: any[]) => void) => {
            setIsLoading(true);

            try {
                if (displayName && displayName !== "dashboard") {
                    // Check if sortValue has a valid mapping
                    const sortOption = sortMap[sortValue?.toLowerCase() || ""];

                    if (sortOption) {
                        const { field, direction } = sortOption;
                        const pageName = "folders-assets";

                        // Wrap callback API in a Promise to use try/catch properly
                        await new Promise<void>((resolve, reject) => {
                            getAssetsSortBy(X_SAAS_Key, user_name, pageName, cleanedPath, field, direction, 0, 100,
                                (error: any, data: any) => {
                                    if (error) {
                                        console.error("Error fetching subAssets:", error);
                                        reject(error);
                                        return;
                                    }
                                    if (data?.folders) {
                                        const fileDetails: AssetDetail[] = data.files?.map((file: any) => ({
                                            name: file.name,
                                            file_ext: file.info?.file_ext,
                                            uuid: file.uuid,
                                            size: file.size?.pretty,
                                            type: file.type,
                                            img_h: file.info?.img_h,
                                            img_w: file.info?.img_w,
                                            preview: file.info?.preview,
                                            thumbnail: file.info?.thumbnail
                                                ?? file.info?.video_gif
                                                ?? file.url.public,
                                            url: file.url.path
                                        })) || [];

                                        setAllSubAssetDetails(fileDetails);
                                        const urls = fileDetails
                                            .map((file: { thumbnail?: string }) => file.thumbnail)
                                            .filter((url): url is string => Boolean(url));
                                        setAllAssetUrls(urls);
                                    }
                                    resolve();
                                }
                            );
                        });

                        await new Promise<void>((resolve, reject) => {
                            getSubFoldersSortBy(X_SAAS_Key, user_name, cleanedPath, field, direction, 0,
                                (error: any, data: any) => {
                                    if (error) {
                                        console.error("Error fetching subfolders:", error);
                                        reject(error);
                                        return;
                                    }
                                    if (data?.folders) {
                                        const subFolders = data.folders.map((folder: any) => ({
                                            name: folder.name,
                                            count: {
                                                files_direct: folder.count.files_direct,
                                                files_recursive: folder.count.files_recursive,
                                            },
                                        }));
                                        setAllSubFoldersNames(subFolders);
                                        onFoldersChange(subFolders);
                                        console.log("Subfolders updated:", subFolders);
                                    }
                                    resolve();
                                }
                            );
                        });
                    } else {
                        // default fetch folder content
                        await fetchFolderContent();
                    }
                }
            } catch (err) {
                console.error("Error in handleFolderFetch:", err);
            } finally {
                setIsLoading(false);
            }
        };

        const fetchFolderContent = async () => {
            try {
                const data = await getFolderContents(currentSaasKey, user_name, cleanedPath);

                const fileDetails: AssetDetail[] = data.files?.map((file: any) => ({
                    name: file.name,
                    file_ext: file.info?.file_ext,
                    uuid: file.uuid,
                    size: file.size?.pretty,
                    type: file.type,
                    img_h: file.info?.img_h,
                    img_w: file.info?.img_w,
                    preview: file.info?.preview,
                    thumbnail: file.info?.thumbnail
                        ?? file.info?.video_gif
                        ?? file.url.public,
                    url: file.url.path
                })) || [];

                setAllSubFoldersNames(data?.folders || []);
                setAllSubAssetDetails(fileDetails);

                const urls = fileDetails
                    .map((file: { thumbnail?: string }) => file.thumbnail)
                    .filter((url): url is string => Boolean(url));
                setAllAssetUrls(urls);

                setFolderCache(prev => ({
                    ...prev,
                    [cacheKey]: { folders: data?.folders || [], files: fileDetails, urls }
                }));
            } catch (error) {
                console.error("Error fetching folder content:", error);
            }
        };

        handleFolderFetch(currentSaasKey, user_name, displayName, setAllSubFoldersNames);
    }, [currentSaasKey, user_name, folderStack, path]);

    const handleShowAssetDetails = (assetUrl: string) => {
        console.log("Clicked assetUrl:", assetUrl);

        const selectedAsset = allSubAssetDetails.find((asset) => {
            const fullUrl = `https://${user_name}.filerobot.com${asset.url}`;
            return asset.thumbnail === assetUrl || fullUrl === assetUrl;
        });

        if (selectedAsset) {
            const fullUrl = `https://${user_name}.filerobot.com${selectedAsset.url}`;
            const updatedAsset = { ...selectedAsset, url: fullUrl };
            console.log("Updated Asset Object:", updatedAsset);

            navigate("/asset-details", {
                state: {
                    selectedAsset: updatedAsset,
                    pageName: "folders-assets",
                    folderStack,
                    path,
                    page
                },
            });
        } else {
            console.warn("No asset found for:", assetUrl);
        }
    };

    const handleSubFolderClick = (folderName: string) => {
        const newPath = `${folderStack[folderStack.length - 1]}/${folderName}`;
        setFolderStack(prev => [...prev, newPath]);
    };

    const handleBackToFolders = () => {
        if (folderStack.length <= 1) {
            navigate('/dashboard', { state: { defaultTab: 1, path } });
            return;
        }
        const newStack = [...folderStack];
        newStack.pop();
        setFolderStack(newStack);
        fetchFolder(newStack[newStack.length - 1]);
    };

    const fetchFolder = async (folderPath: string) => {
        const cacheKey = `${user_name}:${folderPath}`;
        if (folderCache[cacheKey]) {
            const cached = folderCache[cacheKey];
            setAllSubFoldersNames(cached.folders);
            setAllSubAssetDetails(cached.files);
            setAllAssetUrls(cached.urls);
            return;
        }

        setIsLoading(true);
        try {
            const data = await getFolderContents(currentSaasKey!, user_name!, folderPath);
            const urls = data.files?.map((file: any) =>
                file.info?.thumbnail || file.info?.video_thumbnail || file.url.cdn
            ).filter(Boolean) || [];

            const fileDetails: AssetDetail[] = data.files?.map((file: any) => ({
                name: file.name,
                file_ext: file.info?.file_ext,
                uuid: file.uuid,
                size: file.size?.pretty,
                type: file.type,
                img_h: file.info?.img_h,
                img_w: file.info?.img_w,
                preview: file.info?.preview,
                thumbnail: file.info?.thumbnail
                    ?? file.info?.video_gif
                    ?? file.url.public,
                url: file.url.path
            })) || [];

            setAllSubFoldersNames(data?.folders || []);
            setAllSubAssetDetails(fileDetails);
            setAllAssetUrls(urls);

            setFolderCache(prev => ({
                ...prev,
                [cacheKey]: { folders: data?.folders || [], files: fileDetails, urls }
            }));
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <>
            <Header />

            {/* Back Button & Title */}
            {!isLoading && allSubFoldersNames && allAssetUrls && (
                <Stack direction="row" alignItems="center" spacing={1} sx={{ margin: "12px 6px" }}>
                    <IconButton
                        sx={{
                            padding: "6px",
                            "&:hover": {
                                backgroundColor: "#f3f4f6",
                                borderRadius: "12px",
                            },
                        }}
                        onClick={handleBackToFolders}
                    >
                        <FiArrowLeft size={20} />
                    </IconButton>
                    <Typography fontWeight="bold" sx={{ color: "#000", fontSize: "16px" }}>
                        {`${displayName}`}
                    </Typography>
                </Stack>
            )}

            {/* Search Section */}
            <Search
                pageName="folders-assets"
                displayName={cleanedPath}
                onFoldersChange={setAllSubFoldersNames}
                onAssetsChange={setAllAssetUrls}
            />

            <>
                {/* Folders List */}
                {!isLoading && allSubFoldersNames.length > 0 && (
                    <Box sx={{ padding: 1 }}>
                        <Box
                            sx={{
                                width: "100%",
                                display: "flex",
                                justifyContent: "space-between",
                                alignItems: "center",
                                marginBottom: "12px",
                            }}
                        >
                            <Typography variant="subtitle1" fontWeight={600}>
                                Folders
                            </Typography>
                            <Button
                                size="small"
                                sx={{
                                    fontWeight: 600,
                                    fontSize: 12,
                                    textTransform: "capitalize",
                                    color: "black",
                                }}
                                onClick={handleFoldersToggle}
                            >
                                {showAllFolders ? "Show Less" : "See All"}
                            </Button>
                        </Box>

                        <List>
                            {allSubFoldersNames.map((folder, idx) => (
                                <ListItem
                                    key={idx}
                                    component="button"
                                    disableGutters
                                    sx={{
                                        borderRadius: 2,
                                        background: "transparent",
                                        minHeight: 44,
                                        gap: "8px",
                                        marginBottom: "8px",
                                        boxShadow: "none",
                                        border: "none",
                                        cursor: "pointer",
                                    }}
                                    onClick={() => handleSubFolderClick(folder.name)}
                                >
                                    <ListItemIcon sx={{ minWidth: 36 }}>
                                        <Box
                                            sx={{
                                                background: "#F4F4F5",
                                                borderRadius: 2,
                                                width: 40,
                                                height: 40,
                                                display: "flex",
                                                alignItems: "center",
                                                justifyContent: "center",
                                            }}
                                        >
                                            <MdOutlineWindow size={20} />
                                        </Box>
                                    </ListItemIcon>
                                    <Tooltip
                                        title={`${folder?.count?.files_direct} direct files (${folder?.count?.files_recursive} total)`}
                                        arrow
                                        placement="top"
                                    >
                                        <ListItemText
                                            primary={
                                                folder.name.length > 25
                                                    ? folder.name.substring(0, 25) + "..."
                                                    : folder.name
                                            }
                                            primaryTypographyProps={{ fontSize: 15, fontWeight: 500 }}
                                        />
                                    </Tooltip>
                                </ListItem>
                            ))}
                        </List>
                    </Box>
                )}

                {/* Assets Grid */}
                {!isLoading && allAssetUrls.length > 0 && (
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, margin: 1 }}>
                        {/* Assets Title and Pagination */}
                        <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 0.5 }}>
                            <Stack spacing={2} direction="row" alignItems="center">
                                {page > 0 && (
                                    <Tooltip title="Back to First" placement="top" arrow>
                                        <IconButton
                                            onClick={handleBackToFirst}
                                            size="small"
                                            sx={{ p: 0.5, minWidth: "auto" }}
                                        >
                                            <IoMdArrowRoundBack size={16} />
                                        </IconButton>
                                    </Tooltip>
                                )}
                                <Typography variant="subtitle1" fontWeight={600}>
                                    Assets
                                </Typography>
                            </Stack>
                            <Stack>
                                <TablePagination
                                    component="div"
                                    count={allAssetUrls.length}
                                    page={page}
                                    onPageChange={handlePageChange}
                                    rowsPerPage={PAGE_SIZE}
                                    rowsPerPageOptions={[]}
                                    ActionsComponent={CustomTablePaginationActions}
                                    labelDisplayedRows={({ from, to, count }) => `${from}-${to} of ${count}`}
                                />
                            </Stack>
                        </Box>

                        {/* Assets Grid */}
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mb: 2 }}>
                            {Array.from({ length: Math.ceil(visibleAssets.length / 2) }).map((_, rowIdx) => (
                                <Box key={rowIdx} sx={{ display: 'flex', gap: 1 }}>
                                    {visibleAssets.slice(rowIdx * 2, rowIdx * 2 + 2).map((assetUrl, idx) => {
                                        const previewSrc = getPreviewSrc(assetUrl);

                                        return (
                                            <Box
                                                key={idx}
                                                sx={{
                                                    position: "relative",
                                                    width: '50%',
                                                    "&:hover .eyeIcon": { opacity: 1 },
                                                }}
                                            >
                                                <Box
                                                    component="img"
                                                    src={previewSrc}
                                                    alt="asset"
                                                    onError={(e) => { (e.currentTarget as HTMLImageElement).src = DEFAULT_PREVIEW }}
                                                    sx={{
                                                        width: '100%',
                                                        height: 100,
                                                        borderRadius: 2,
                                                        objectFit: 'cover',
                                                    }}
                                                />
                                                <IconButton
                                                    className="eyeIcon"
                                                    onClick={() => handleShowAssetDetails(assetUrl)}
                                                    sx={{
                                                        position: "absolute",
                                                        top: 8,
                                                        right: 8,
                                                        bgcolor: "#F2F2F2",
                                                        opacity: 0,
                                                        transition: "opacity 0.3s",
                                                        "&:hover": { bgcolor: "white" },
                                                    }}
                                                >
                                                    <IoEyeOutline size={14} />
                                                </IconButton>
                                            </Box>
                                        );
                                    })}
                                </Box>
                            ))}
                        </Box>
                    </Box >

                )}
            </>

            {/* Empty Folder */}
            {!isLoading && allSubFoldersNames.length === 0 && allAssetUrls.length === 0 && (
                <NotFound />
            )}
        </>
    );
};

export default FoldersAssets;
