export const getFoldersList = async (
  x_filerobot_key: string,
  user_name: string,
  callback: (error: Error | null, data: any | null) => void
): Promise<void> => {
  try {
    if (!process.env.API_BASE_URL) {
      throw new Error("API_BASE_URL is not defined");
    }

    const url = `${process.env.API_BASE_URL}/${user_name}/v5/folders`;

    const myHeaders = new Headers();
    myHeaders.append("Content-Type", "application/json");
    myHeaders.append("X-Filerobot-Key", x_filerobot_key);

    const requestOptions = {
      method: "GET",
      headers: myHeaders,
    };

    const response = await fetch(url, requestOptions);

    const contentType = response.headers.get("content-type");
    if (contentType && contentType.includes("application/json")) {
      const result = await response.json();

      if (result.status === "success") {
        console.log(result);
        callback(null, result);
      } else {
        callback(new Error("API responded but status not success"), null);
      }
    } else {
      // Not JSON, get raw text to debug
      const text = await response.text();
      console.error("Expected JSON but got:", text);
      callback(new Error("Response is not JSON"), null);
    }
  } catch (error: any) {
    console.error("Fetch error:", error);
    callback(error, null);
  }
};
