import React, { useState, useEffect } from 'react';
import { Box, Stack, Typography, FormControlLabel, Checkbox, FormControl, MenuItem, AppBar, Toolbar, IconButton, Tooltip, InputAdornment, TextField, Button } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import Toast from '../../toast/Toast';
import UIText from '../../../utilities/textResource';
import { IoMdArrowRoundBack } from "react-icons/io";
import { sort_by } from '../../../utilities/allData';
import { LuArrowDownUp } from 'react-icons/lu';

const Setting: React.FC = () => {
    const navigate = useNavigate();
    const [success, setSuccess] = useState('');
    const [rememberUserName, setRememberUserName] = useState<boolean>(false);
    const [rememberUserToken, setRememberUserToken] = useState<boolean>(false);
    const [defaultSort, setDefaultSort] = useState<string>(sort_by[5].toLowerCase());
    const [userName, setUserName] = useState<string>('');
    const [userToken, setUserToken] = useState<string>('');

    useEffect(() => {
        const savedSort = localStorage.getItem('default-sort');
        const savedUserName = localStorage.getItem('username');
        const savedUserToken = localStorage.getItem('userToken');
        const rememberUserName = localStorage.getItem('remember-username-enabled');
        const rememberUserToken = localStorage.getItem('remember-usertoken-enabled');

        if (savedSort) setDefaultSort(savedSort);
        if (savedUserName) setUserName(savedUserName);
        if (savedUserToken) setUserToken(savedUserToken);

        // use 'check' / 'not-check' flag
        setRememberUserName(rememberUserName === 'check');
        setRememberUserToken(rememberUserToken === 'check');
    }, []);

    const handleBackToDashboard = () => {
        navigate("/dashboard");
    };

    const handleSortChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setDefaultSort(e.target.value);
    };

    const handleSaveSetting = () => {
        localStorage.setItem('default-sort', defaultSort);

        // Save remember username status: 'check' or 'not-check'
        localStorage.setItem('remember-username-enabled', rememberUserName ? 'check' : 'not-check');
        localStorage.setItem('remember-usertoken-enabled', rememberUserToken ? 'check' : 'not-check');

        setSuccess('Settings saved successfully!');
    };

    return (
        <>
            <Box>
                {/* App Bar */}
                <Box sx={{ flexGrow: 1 }}>
                    <AppBar position="static">
                        <Toolbar sx={{ display: "flex", justifyContent: "left", alignItems: "center", gap: "16px" }}>
                            <Tooltip title="Back to dashboard" placement="left-start">
                                <IconButton
                                    edge="end"
                                    color="inherit"
                                    aria-label="back to dashboard"
                                    onClick={handleBackToDashboard}
                                    sx={{ fontSize: "20px", marginLeft: "-12px" }}
                                >
                                    <IoMdArrowRoundBack />
                                </IconButton>
                            </Tooltip>

                            <Typography sx={{ fontSize: "18px", fontWeight: 500, color: '#fff' }}>
                                {UIText.setting.title}
                            </Typography>
                        </Toolbar>
                    </AppBar>
                </Box>

                {/* Remember userName */}
                <Stack spacing={3} sx={{ marginTop: "16px" }}>
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={rememberUserName}
                                onChange={(e) => setRememberUserName(e.target.checked)}
                                color="primary"
                                sx={{
                                    '& .MuiSvgIcon-root': {
                                        fontSize: 20,
                                    },
                                }}
                            />
                        }
                        label={
                            <Typography variant="body1" sx={{ whiteSpace: 'nowrap', fontSize: '13px' }}>
                                Remember my user name (
                                <Typography
                                    component="span"
                                    color="primary"
                                    sx={{
                                        cursor: 'pointer',
                                        textDecoration: 'none',
                                        fontSize: "12px",
                                        '&:hover': {
                                            textDecoration: 'underline',
                                        },
                                    }}
                                >
                                    {userName || 'not set'}
                                </Typography>
                                )
                            </Typography>
                        }
                    />
                </Stack>

                { /* Remember userToken */}
                <Stack spacing={3} sx={{ marginTop: "-6px" }}>
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={rememberUserToken}
                                onChange={(e) => setRememberUserToken(e.target.checked)}
                                color="primary"
                                sx={{
                                    '& .MuiSvgIcon-root': {
                                        fontSize: 20,
                                    },
                                }}
                            />
                        }
                        label={
                            <Typography variant="body1" sx={{ whiteSpace: 'nowrap', fontSize: '13px' }}>
                                Remember my user token (
                                <Typography
                                    component="span"
                                    color="primary"
                                    sx={{
                                        cursor: 'pointer',
                                        textDecoration: 'none',
                                        fontSize: "12px",
                                        '&:hover': {
                                            textDecoration: 'underline',
                                        },
                                    }}
                                >
                                    {userToken || 'not set'}
                                </Typography>
                                )
                            </Typography>
                        }
                    />
                </Stack>

                {/* Sort Options */}
                <FormControl sx={{ gap: "8px", margin: "8px 12px", width: "92%" }}>
                    <TextField
                        select
                        variant="outlined"
                        size="small"
                        value={defaultSort}
                        onChange={handleSortChange}
                        placeholder="Sort by"
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <LuArrowDownUp />
                                </InputAdornment>
                            ),
                        }}
                        sx={{
                            width: "100%",
                            maxWidth: "600px",
                        }}
                    >
                        {sort_by.map((option) => (
                            <MenuItem key={option} value={option.toLowerCase()}>
                                {option}
                            </MenuItem>
                        ))}
                    </TextField>
                </FormControl>

                {/* Save Button */}
                <Stack sx={{ display: "flex", justifyContent: "end", alignItems: "end", marginRight: "14px" }}>
                    <Button
                        variant="contained"
                        sx={{
                            color: "#fff",
                            fontWeight: 600,
                            padding: "6px 40px",
                            textTransform: "capitalize",
                        }}
                        onClick={handleSaveSetting}
                    >
                        Save
                    </Button>
                </Stack>
            </Box>

            {/* Toast Notification */}
            {success && <Toast success={success} />}
        </>
    );
};

export default Setting;