import { DEFAULT_PREVIEW, DOCX_PREVIEW, PDF_PREVIEW } from "./allData";

const getFileExtension = (url: string): string => {
    try {
        const cleanUrl = url.split('?')[0].split('#')[0];
        return cleanUrl.split('.').pop()?.toLowerCase() || '';
    } catch {
        return '';
    }
};

export const getPreviewSrc = (url?: string): string => {
    if (!url) return DEFAULT_PREVIEW;

    const ext = getFileExtension(url);

    if (ext === 'doc' || ext === 'docx') {
        return DOCX_PREVIEW;
    }

    if (ext === 'pdf') {
        return PDF_PREVIEW;
    }

    return url || DEFAULT_PREVIEW;
};