import React, { useState, useEffect } from 'react';
import { Box, Tabs, Tab } from '@mui/material';
import UIText from '../../../utilities/textResource';
import FoldersView from './folders/page';
import AssetsView from './assets/page';
import { TabsPageProps } from '../../../utilities/types';
import { useData } from '../../../hook/DataContext';

const TabsPage: React.FC<TabsPageProps> = ({ defaultTab }) => {
    const [selectedTab, setSelectedTab] = useState(defaultTab);
    const { allFolders, allAssetDetails, isLoading } = useData();

    const handleTabChange = (_: React.SyntheticEvent, newValue: number) => {
        setSelectedTab(newValue);
    };

    return (
        <>
            {!isLoading && (
                <>
                    <Tabs
                        value={selectedTab}
                        onChange={handleTabChange}
                        variant="fullWidth"
                        sx={{ margin: 1 }}
                    >
                        <Tab
                            label={UIText.tabs.assets_view.title}
                            sx={{
                                textTransform: "capitalize",
                                color: "#000000",
                                fontWeight: 400,
                                "&.Mui-selected": { fontWeight: 500 }
                            }}
                        />
                        <Tab
                            label={UIText.tabs.folders_view.title}
                            sx={{
                                textTransform: "capitalize",
                                color: "#000000",
                                fontWeight: 400,
                                "&.Mui-selected": { fontWeight: 500 }
                            }}
                        />
                    </Tabs>

                    <Box sx={{ padding: 2 }}>
                        {selectedTab === 0 && allAssetDetails && (
                            <AssetsView />
                        )}
                        {selectedTab === 1 && allFolders.length > 0 && allAssetDetails.length > 0 && (
                            <FoldersView />
                        )}
                    </Box>
                </>
            )}
        </>
    );
};

export default TabsPage;