export const refreshSASSKey = (X_SAAS_Key: string, x_session_token: string, expires_X_SAAS_Key: string, user_name: string, callback: (error: any, data?: any, notExpireSASSKey?: string) => void) => {
    try {
        // Parse the timestamp (handles ISO 8601 format like "2025-07-26T05:57:43+00:00")
        const tokenTimestamp = new Date(expires_X_SAAS_Key);
        const currentTime = new Date();

        // Validate that the timestamp was parsed correctly
        if (isNaN(tokenTimestamp.getTime())) {
            throw new Error("Invalid timestamp format");
        }

        // Calculate time difference in milliseconds
        const timeDifference = currentTime.getTime() - tokenTimestamp.getTime();

        // Check if token is expired (assuming 24 hours validity)
        const tokenValidityHours = 2;
        const tokenValidityMs = tokenValidityHours * 60 * 60 * 1000;

        if (timeDifference >= tokenValidityMs) {
            // Token is expired, need to refresh
            console.log("Token expired. Time difference:", timeDifference / (60 * 60 * 1000), "hours");

            const myHeaders = new Headers();
            myHeaders.append("X-Filerobot-Key", X_SAAS_Key);
            myHeaders.append("X-Session-Token", x_session_token);

            const requestOptions = {
                method: "POST",
                headers: myHeaders
            };

            fetch(`${process.env.AUTH_BASE_URL}/${user_name}/v5/key/renew`, requestOptions)
                .then((response) => response.json())
                .then((result) => {
                    if (result && result.status === "success") {
                        // Update localStorage with new timestamp
                        localStorage.setItem("X_SAAS_Key", result.keychain.tokens.airstore_key);
                        localStorage.setItem("expires_X_SAAS_Key", result.api_info.timestamp);

                        console.log("refreshSASSKey refreshed successfully");
                        callback(null, result);
                    } else {
                        console.log("refreshSASSKey refresh failed:", result);
                        callback(result);
                    }
                })
                .catch((error) => {
                    console.log("refreshSASSKey refresh error:", error);
                    callback(error);
                });
        } else {
            // Token is still valid
            const remainingTime = tokenValidityMs - timeDifference;
            const remainingHours = Math.floor(remainingTime / (60 * 60 * 1000));
            const remainingMinutes = Math.floor((remainingTime % (60 * 60 * 1000)) / (60 * 1000));

            const notExpireSASSKey = `refreshSASSKey not expired yet. Remaining time: ${remainingHours} hours ${remainingMinutes} minutes`;
            console.log("refreshSASSKey still valid:", notExpireSASSKey);
            callback("refreshSASSKey not expired yet", null, notExpireSASSKey);
        }
    } catch (error) {
        console.log("refreshSASSKey error:", error);
        callback(error);
    }
};