import React, { useState, useEffect } from 'react';
import { Box, Typography, Button, List, ListItem, ListItemIcon, ListItemText, Tooltip, Stack, IconButton, TablePagination, TablePaginationProps } from '@mui/material';
import { MdOutlineWindow } from "react-icons/md";
import { useNavigate, useLocation } from 'react-router-dom';
import { FiChevronLeft, FiChevronRight } from 'react-icons/fi';
import { IoMdArrowRoundBack } from 'react-icons/io';
import { TabsPageProps } from '../../../../utilities/types';
import { IoEyeOutline } from 'react-icons/io5';
import { useData } from '../../../../hook/DataContext';
import NotFound from '../notFound';
import { DEFAULT_PREVIEW } from '../../../../utilities/allData';
import { getPreviewSrc } from '../../../../utilities/getPreviewSrc';

const FoldersView: React.FC<TabsPageProps> = () => {
    const PAGE_SIZE = 50;
    const navigate = useNavigate();
    const location = useLocation();
    const [page, setPage] = useState(0);
    const { allFolders, allRootDirAssetDetails, isLoading } = useData();
    const [allAssetUrls, setAllAssetUrls] = useState([]);
    const [showAllFolders, setShowAllFolders] = useState(false);
    const visibleFolders = showAllFolders ? allFolders : allFolders.slice(0, 5);
    const visibleAssets = allAssetUrls.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
    const handleFoldersToggle = () => setShowAllFolders((prev) => !prev);
    const user_name = localStorage.getItem("user-name");

    useEffect(() => {
        if (allRootDirAssetDetails && allRootDirAssetDetails.length > 0) {
            console.log("AssetsView allAssetUrls:", allRootDirAssetDetails);

            const urls = allRootDirAssetDetails
                .map((file: { thumbnail?: string }) => file.thumbnail)
                .filter((url): url is string => Boolean(url));
            setAllAssetUrls(urls);
        }

        if (location.state?.page !== undefined) {
            setPage(location.state.page);
        }
    }, [allRootDirAssetDetails, location.state]);

    const handlePageChange = (
        _event: React.MouseEvent<HTMLButtonElement> | null,
        newPage: number
    ) => {
        setPage(newPage);
    };

    const handleBackToFirst = () => {
        setPage(0);
    };

    // Custom pagination actions component
    const CustomTablePaginationActions = ({
        count,
        page,
        rowsPerPage,
        onPageChange,
    }: Pick<
        TablePaginationProps,
        'count' | 'page' | 'rowsPerPage' | 'onPageChange'
    >) => {
        const handleBack = (event: React.MouseEvent<HTMLButtonElement>) => {
            onPageChange(event, page - 1);
        };

        const handleNext = (event: React.MouseEvent<HTMLButtonElement>) => {
            onPageChange(event, page + 1);
        };

        return (
            <>
                <Box sx={{ flexShrink: 0, display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    <IconButton
                        onClick={handleBack}
                        disabled={page === 0}
                        sx={{ p: 0.5, minWidth: 'auto' }}
                    >
                        <FiChevronLeft size={16} />
                    </IconButton>
                    <IconButton
                        onClick={handleNext}
                        disabled={page >= Math.ceil(count / rowsPerPage) - 1}
                        sx={{ p: 0.5, minWidth: 'auto' }}
                    >
                        <FiChevronRight size={16} />
                    </IconButton>
                </Box>
            </>
        );
    };

    const handleShowAssetDetails = (assetUrl: string) => {
        const selectedAsset = allRootDirAssetDetails.find((asset) => {
            const fullUrl = `https://${user_name}.filerobot.com${asset.url}`;
            return asset.thumbnail === assetUrl || fullUrl === assetUrl;
        });

        if (selectedAsset) {
            let updatedAsset = selectedAsset;

            // Only update URL if matched by asset.url, not by thumbnail
            const fullUrl = `https://${user_name}.filerobot.com${selectedAsset.url}`;
            if (fullUrl === assetUrl) {
                updatedAsset = { ...selectedAsset, url: fullUrl };
            }

            navigate("/asset-details", {
                state: {
                    selectedAsset: updatedAsset,
                    pageName: "folders-assets",
                    page,
                },
            });
        } else {
            console.log("No asset found for URL:", assetUrl);
        }
    };

    const handleFetchAssetsList = async (path: string) => {
        console.log(path);

        // Pass the path via navigation state
        navigate('/folders-assets', { state: { path } });
    };

    return (
        <>
            {allFolders.length === 0 && allAssetUrls.length === 0 ? (
                <NotFound />
            ) : (
                <>
                    {/* Folders Section */}
                    {!isLoading && allFolders?.length > 0 && (
                        <>
                            <Box
                                sx={{
                                    width: "100%",
                                    display: "flex",
                                    justifyContent: "space-between",
                                    alignItems: "center",
                                    marginBottom: "12px",
                                }}
                            >
                                <Typography variant="subtitle1" fontWeight={600}>
                                    Folders
                                </Typography>
                                <Button
                                    size="small"
                                    sx={{
                                        fontWeight: 600,
                                        fontSize: 12,
                                        textTransform: "capitalize",
                                        color: "black",
                                    }}
                                    onClick={handleFoldersToggle}
                                >
                                    {showAllFolders ? "Show Less" : "See All"}
                                </Button>
                            </Box>

                            <List>
                                {visibleFolders.map((folder, idx) => (
                                    <ListItem
                                        key={idx}
                                        sx={{
                                            borderRadius: 2,
                                            background: "transparent",
                                            minHeight: 44,
                                            gap: "8px",
                                            marginBottom: "8px",
                                            boxShadow: "none",
                                            border: "none",
                                            cursor: "pointer",
                                        }}
                                        component="button"
                                        disableGutters
                                        onClick={() => handleFetchAssetsList(folder.path)}
                                    >
                                        <ListItemIcon sx={{ minWidth: 36 }}>
                                            <Box
                                                sx={{
                                                    background: "#F4F4F5",
                                                    borderRadius: 2,
                                                    display: "flex",
                                                    alignItems: "center",
                                                    justifyContent: "center",
                                                    width: 40,
                                                    height: 40,
                                                }}
                                            >
                                                <MdOutlineWindow size={20} />
                                            </Box>
                                        </ListItemIcon>
                                        <Tooltip title={`${folder.count.files_direct} direct files (${folder.count.files_recursive} total)`} placement="top" arrow>
                                            <ListItemText
                                                primary={
                                                    folder.short
                                                        ? folder.name.substring(0, 25) + "..."
                                                        : folder.name
                                                }
                                                primaryTypographyProps={{
                                                    fontSize: 15,
                                                    fontWeight: 500,
                                                    bgcolor: "transparent",
                                                }}
                                            />
                                        </Tooltip>
                                    </ListItem>
                                ))}
                            </List>
                        </>
                    )}

                    {/* Assets Section */}
                    {!isLoading && allAssetUrls?.length > 0 && (
                        <Box sx={{ mt: 2 }}>
                            {/* Assets Title and Pagination */}
                            <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 0.5 }}>
                                <Stack spacing={2} direction="row" alignItems="center">
                                    {page > 0 && (
                                        <Tooltip title="Back to First" placement="top" arrow>
                                            <IconButton
                                                onClick={handleBackToFirst}
                                                size="small"
                                                sx={{ p: 0.5, minWidth: "auto" }}
                                            >
                                                <IoMdArrowRoundBack size={16} />
                                            </IconButton>
                                        </Tooltip>
                                    )}
                                    <Typography variant="subtitle1" fontWeight={600}>
                                        Assets
                                    </Typography>
                                </Stack>
                                <Stack>
                                    <TablePagination
                                        component="div"
                                        count={allAssetUrls.length}
                                        page={page}
                                        onPageChange={handlePageChange}
                                        rowsPerPage={PAGE_SIZE}
                                        rowsPerPageOptions={[]}
                                        ActionsComponent={CustomTablePaginationActions}
                                        labelDisplayedRows={({ from, to, count }) => `${from}-${to} of ${count}`}
                                    />
                                </Stack>
                            </Box>

                            {/* Assets Grid */}
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mb: 2 }}>
                                {Array.from({ length: Math.ceil(visibleAssets.length / 2) }).map((_, rowIdx) => (
                                    <Box key={rowIdx} sx={{ display: 'flex', gap: 1 }}>
                                        {visibleAssets.slice(rowIdx * 2, rowIdx * 2 + 2).map((assetUrl, idx) => {
                                            const previewSrc = getPreviewSrc(assetUrl);

                                            return (
                                                <Box
                                                    key={idx}
                                                    sx={{
                                                        position: "relative",
                                                        width: '50%',
                                                        "&:hover .eyeIcon": { opacity: 1 },
                                                    }}
                                                >
                                                    <Box
                                                        component="img"
                                                        src={previewSrc}
                                                        alt="asset"
                                                        onError={(e) => { (e.currentTarget as HTMLImageElement).src = DEFAULT_PREVIEW }}
                                                        sx={{
                                                            width: '100%',
                                                            height: 100,
                                                            borderRadius: 2,
                                                            objectFit: 'cover',
                                                        }}
                                                    />
                                                    <IconButton
                                                        className="eyeIcon"
                                                        onClick={() => handleShowAssetDetails(assetUrl)}
                                                        sx={{
                                                            position: "absolute",
                                                            top: 8,
                                                            right: 8,
                                                            bgcolor: "#F2F2F2",
                                                            opacity: 0,
                                                            transition: "opacity 0.3s",
                                                            "&:hover": { bgcolor: "white" },
                                                        }}
                                                    >
                                                        <IoEyeOutline size={14} />
                                                    </IconButton>
                                                </Box>
                                            );
                                        })}
                                    </Box>
                                ))}
                            </Box>
                        </Box>
                    )}
                </>
            )}
        </>
    );
};

export default FoldersView;