export const getMFACode = async (mfa_Code: string, mfa_uuid: string, callback: (error: Error | null, data: any | null) => void): Promise<void> => {
    const myHeaders = new Headers();
    myHeaders.append("X-Company-Token", "a99575d4-94a9-42a2-b599-89f23142fe4e");
    myHeaders.append("X-Project-Token", "frzjaqrbb");
    myHeaders.append("Content-Type", "application/json");

    const raw = JSON.stringify({
        "mfa": {
            "code": mfa_Code
        }
    });

    const requestOptions = {
        method: "POST",
        headers: myHeaders,
        body: raw
    };

    fetch(`${process.env.AUTH_BASE_URL}/api/mfa/${mfa_uuid}/validate`, requestOptions)
        .then((response) => response.json())
        .then((result) => {
            console.log(result);

            if (result && result.status === "success") {
                localStorage.setItem("session_uuid", result.session_uuid);
                localStorage.setItem("x-company-token", result.companies[0].uuid);
                localStorage.setItem("expires_x_session_token", result.api_info.timestamp);
                callback(null, result);
            } else {
                console.error("Authentication failed: ", result.msg);
                callback(result, null);
            }
        })
        .catch((error) => {
            console.error(error);
            callback(error, null);
        });
};