import React, { useState } from 'react';
import { Box, AppBar, Toolbar, Typography, IconButton, Tooltip, Menu, MenuItem } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { BsThreeDotsVertical } from 'react-icons/bs';
import UIText from '../../utilities/textResource';

const Header: React.FC = () => {
    const navigate = useNavigate();
    const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
    const open = Boolean(anchorEl);

    const handleOpenMenu = (event: React.MouseEvent<HTMLElement>) => {
        setAnchorEl(event.currentTarget);
    };

    const handleCloseMenu = () => {
        setAnchorEl(null);
    };

    const handleSettings = () => {
        handleCloseMenu();
        console.log("Settings clicked");

        navigate("/settings");
    };

    const handleLogout = () => {
        handleCloseMenu();
        console.log("Logout clicked");

        // Clear all authentication data from localStorage
        localStorage.removeItem('session_uuid');
        localStorage.removeItem("x-project-token");
        localStorage.removeItem("x-company-token");
        localStorage.removeItem("username");
        localStorage.removeItem("X_SAAS_Key");
        localStorage.removeItem("expires_X_SAAS_Key");
        localStorage.removeItem("expires_x_session_token");
        navigate("/");
    };

    return (
        <>
            <Box sx={{ flexGrow: 1 }}>
                <AppBar position="static">
                    <Toolbar sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                        <Typography
                            sx={{
                                fontSize: "18px",
                                fontWeight: 500,
                                color: '#fff',
                            }}
                        >
                            {UIText.home.title}
                        </Typography>

                        <Tooltip title="Menu" placement="left-start">
                            <IconButton
                                edge="end"
                                color="inherit"
                                aria-label="menu"
                                onClick={handleOpenMenu}
                                sx={{ fontSize: "20px" }}
                            >
                                <BsThreeDotsVertical />
                            </IconButton>
                        </Tooltip>

                        <Menu
                            anchorEl={anchorEl}
                            open={open}
                            onClose={handleCloseMenu}
                            anchorOrigin={{
                                vertical: 'bottom',
                                horizontal: 'right',
                            }}
                            transformOrigin={{
                                vertical: 'top',
                                horizontal: 'right',
                            }}
                        >
                            <MenuItem onClick={handleSettings}>Settings</MenuItem>
                            <MenuItem onClick={handleLogout}>Logout</MenuItem>
                        </Menu>
                    </Toolbar>
                </AppBar>
            </Box>
        </>
    );
};

export default Header;