import React, { useEffect } from "react";
import { Box, Stack, Button, Typography } from "@mui/material";
import { Image } from "@fluentui/react-components";
import { useNavigate } from "react-router-dom";
import UIText from "../../../utilities/textResource";

const Login: React.FC = () => {
    const navigate = useNavigate();
    const session_uuid = localStorage.getItem("session_uuid");

    // check if user already logged-in then move to the dashboard if not then got to login
    useEffect(() => {
        if (session_uuid) {
            navigate("/dashboard");
        } else {
            navigate("/");
        }
    }, [])

    const handleConnect = () => {
        console.log("Connect Clicked!");

        navigate('/email-password');
    }

    let dialog: Office.Dialog;
    const handleConnectOAuth2 = () => {
        const clientId = '9f792352-2dce-46cf-a6fb-6fcbf3a02fbd';
        const redirectUri = 'https://oauth2.sfxconnector.com/api/oauth/ms365/authorized';

        const authUrl = `https://oauth2.sfxconnector.com/oauth/authorize?` +
            `response_type=code&` +
            `client_id=${clientId}&` +
            `redirect_uri=${encodeURIComponent(redirectUri)}`;

        Office.context.ui.displayDialogAsync(authUrl, { height: 70, width: 40 }, (asyncResult) => {
            if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
                dialog = asyncResult.value;
                dialog.addEventHandler(Office.EventType.DialogMessageReceived, processMessage);
            } else {
                console.error("Dialog failed to open:", asyncResult.error.message);
            }
        });
    };

    const processMessage = (arg: any) => {
        try {
            if ("message" in arg) {
                const message = JSON.parse(arg.message);

                // Handle access token directly
                if (message.access_token) {
                    console.log("Access Token received:", message.access_token);

                    // Save token to localStorage/sessionStorage for your add-in
                    localStorage.setItem("access_token", message.access_token);

                    // Optionally save refresh token
                    if (message.refresh_token) {
                        localStorage.setItem("refresh_token", message.refresh_token);
                    }

                    // Navigate to dashboard
                    navigate("/dashboard");
                }
                else if (message.error) {
                    console.error("OAuth2 Error:", message.error);
                }
            } else if ("error" in arg) {
                console.error("Dialog error:", arg.error);
            }
        } catch (err) {
            console.error("Failed to process message:", err);
        } finally {
            if (dialog) {
                dialog.close();
            }
        }
    };

    return (
        <>
            <Box sx={{ margin: "12% 8px" }}>
                <Typography sx={{ fontSize: "20px", fontWeight: 600, textAlign: "center", paddingTop: "12px" }}>
                    {UIText.login.title_1}
                </Typography>
                <Typography sx={{ fontSize: "20px", fontWeight: 600, textAlign: "center" }}>
                    {UIText.login.title_2}
                </Typography>

                <Stack sx={{ display: "flex", justifyContent: "center", alignItems: "center", margin: "36px 0" }}>
                    <Image src={`${process.env.PORD_URL}/assets/logo-filled.png`} alt="ScaleFlex DAM" height={100} width={100} />
                </Stack>

                <Stack sx={{ margin: "12px 12px" }}>
                    <Button
                        variant="contained"
                        sx={{
                            color: "#fff",
                            fontWeight: 600,
                            textTransform: "capitalize",
                        }}
                        onClick={handleConnectOAuth2}
                    >
                        {UIText.login.connect_via_sso}
                    </Button>
                </Stack>

                <Stack sx={{ margin: "12px 12px" }}>
                    <Button
                        variant="contained"
                        sx={{
                            color: "#fff",
                            fontWeight: 600,
                            textTransform: "none",
                        }}
                        onClick={handleConnect}
                    >
                        {UIText.login.connect_via_user}
                    </Button>
                </Stack>
            </Box>
        </>
    );
}

export default Login;