export const getSAASKey = async (x_session_token: string, x_project_token: string, x_company_token: string, callback: (error: Error | null, data: any | null) => void): Promise<void> => {
    const myHeaders = new Headers();
    myHeaders.append("Content-Type", "application/json");
    myHeaders.append("X-Session-Token", x_session_token);
    myHeaders.append("X-Company-Token", x_company_token);

    const requestOptions = {
        method: "GET",
        headers: myHeaders
    };

    fetch(`${process.env.AUTH_BASE_URL}/api/project/${x_project_token}`, requestOptions)
        .then((response) => response.json())
        .then((result) => {
            if (result.status === "success") {
                console.log(result);
                localStorage.setItem("user-name", result.project.name);
                console.log("X_SAAS_Key", result.keychain.tokens.airstore_key);
                localStorage.setItem("X_SAAS_Key", result.keychain.tokens.airstore_key);
                localStorage.setItem("expires_X_SAAS_Key", result.api_info.timestamp);

                callback(null, result);
            } else {
                callback(result, null);
            }
        })
        .catch((error) => {
            console.error(error);
            callback(error, null);
        });
}