export const insertImgIntoSlide = async (base64Image: string) => {
    try {
        // Ensure the Office context is ready
        await Office.onReady();

        // Insert the image into the current slide
        Office.context.document.setSelectedDataAsync(
            base64Image,
            {
                coercionType: Office.CoercionType.Image,
                imageLeft: 100,
                imageTop: 100,
                imageWidth: 300,
            },
            (asyncResult) => {
                if (asyncResult.status === Office.AsyncResultStatus.Failed) {
                    console.error("Insert image failed:", asyncResult.error.message);
                } else {
                    console.log("Image inserted successfully!");
                }
            }
        );
    } catch (error) {
        console.error("Error inserting image:", error);
    }
}

export const insertSvgIntoSlide = async (svgBase64: string) => {
    try {
        await Office.onReady();
        // Decode Base64 back into SVG XML string
        const svgXml = atob(svgBase64);
        Office.context.document.setSelectedDataAsync(
            svgXml,
            {
                coercionType: Office.CoercionType.XmlSvg
            },
            (asyncResult) => {
                if (asyncResult.status === Office.AsyncResultStatus.Failed) {
                    console.error("Insert SVG failed:", asyncResult.error.message);
                } else {
                    console.log("SVG inserted successfully!");
                }
            }
        );
    } catch (error) {
        console.error("Error inserting SVG:", error);
    }
};

export const insertDocxIntoSlide = async (fileUrl: string) => {
    try {
        await Office.onReady();

        // Step 1: Insert plain text
        Office.context.document.setSelectedDataAsync(
            "Open Document: ",
            { coercionType: Office.CoercionType.Text },
            (asyncResult) => {
                if (asyncResult.status === Office.AsyncResultStatus.Failed) {
                    console.error("Insert DOCX text failed:", asyncResult.error.message);
                } else {
                    console.log("DOCX text inserted successfully!");
                    try {
                        Office.context.document.setSelectedDataAsync(
                            fileUrl,
                            { coercionType: Office.CoercionType.Text },
                            (linkResult) => {
                                if (linkResult.status === Office.AsyncResultStatus.Failed) {
                                    console.warn("Could not attach hyperlink automatically. User may need to add it manually.");
                                } else {
                                    console.log("Hyperlink inserted (if supported).");
                                }
                            }
                        );
                    } catch (linkErr) {
                        console.warn("Adding hyperlink not supported in PowerPoint. Inserted only text.");
                    }
                }
            }
        );
    } catch (error) {
        console.error("Error inserting DOCX:", error);
    }
};
