const X_Company_Token = process.env.X_Company_Token;
const X_Project_Token = process.env.X_Project_Token;

export const refreshXSessionToken = (x_session_token: string, expires_x_session_token: string, callback: (error: any, data?: any, notExpireSASSKey?: string) => void) => {
    try {
        // Parse the timestamp (handles ISO 8601 format like "2025-07-26T05:57:43+00:00")
        const tokenTimestamp = new Date(expires_x_session_token);
        const currentTime = new Date();

        // Validate that the timestamp was parsed correctly
        if (isNaN(tokenTimestamp.getTime())) {
            throw new Error("Invalid timestamp format");
        }

        // Calculate time difference in milliseconds
        const timeDifference = currentTime.getTime() - tokenTimestamp.getTime();

        const tokenValidityHours = 2;
        const tokenValidityMs = tokenValidityHours * 60 * 60 * 1000;

        if (timeDifference >= tokenValidityMs) {
            // Token is expired, need to refresh
            console.log("refreshXSessionToken expired. Time difference:", timeDifference / (60 * 60 * 1000), "hours");

            const myHeaders = new Headers();
            myHeaders.append("X-Session-Token", x_session_token);
            myHeaders.append("X-Company-Token", X_Company_Token);
            myHeaders.append("X-Project-Token", X_Project_Token);

            const requestOptions = {
                method: "POST",
                headers: myHeaders
            };

            fetch(`${process.env.AUTH_BASE_URL}/api/session/${x_session_token}/renew`, requestOptions)
                .then((response) => response.json())
                .then((result) => {
                    if (result && result.status === "success") {
                        // Update localStorage with new timestamp
                        localStorage.setItem("session_uuid", result.session_uuid);
                        localStorage.setItem("expires_x_session_token", result.new_expires);
                        console.log("refreshXSessionToken refreshed successfully");
                        callback(null, result);
                    } else {
                        console.log("refreshXSessionToken refresh failed:", result);
                        callback(result);
                    }
                })
                .catch((error) => {
                    console.log("refreshXSessionToken refresh error:", error);
                    callback(error);
                });
        } else {
            // Token is still valid
            const remainingTime = tokenValidityMs - timeDifference;
            const remainingHours = Math.floor(remainingTime / (60 * 60 * 1000));
            const remainingMinutes = Math.floor((remainingTime % (60 * 60 * 1000)) / (60 * 1000));

            const notExpireXSessionToken = `refreshXSessionToken not expired yet. Remaining time: ${remainingHours} hours ${remainingMinutes} minutes`;
            console.log("refreshXSessionToken still valid:", notExpireXSessionToken);
            callback("refreshXSessionToken not expired yet", null, notExpireXSessionToken);
        }
    } catch (error) {
        console.log("refreshXSessionToken error:", error);
        callback(error);
    }
};