import React, { useState } from 'react';
import { Box, Button, IconButton, Stack, Typography } from '@mui/material';
import { useNavigate, useLocation } from 'react-router-dom';
import ImgLoading from '../../../loader/imgPreviewLoading';
import NotFound from '../notFound'
import Header from '../../header';
import Toast from '../../../toast/Toast';
import { FiArrowLeft } from 'react-icons/fi';
import UIText from '../../../../utilities/textResource';
import { urlToBase64 } from '../../../../utilities/base64';
import { insertDocxIntoSlide, insertImgIntoSlide, insertSvgIntoSlide } from '../../../../utilities/insertIntoSlide';

const DEFAULT_PREVIEW = '/assets/default.jpeg';
const DOCX_PREVIEW = '/assets/docx.png';
const PDF_PREVIEW = '/assets/pdf.png';

const AssetDetails: React.FC = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const [error, setError] = useState("");
    const [isImageLoading, setIsImageLoading] = useState(true);
    const user_name = localStorage.getItem("user-name");

    const { selectedAsset, pageName, path, folderStack, page } = location.state || {};

    const handleBackToAssets = () => {
        if (pageName === "folders-assets" && folderStack) {
            navigate('/folders-assets', { state: { folderStack, path, page } });
        } else {
            const tabIndex = pageName === "folders-assets" ? 1 : 0;
            navigate('/dashboard', { state: { defaultTab: tabIndex, page } });
        }
    };

    const displayName =
        selectedAsset?.name && selectedAsset.name.length > 25
            ? `${selectedAsset.name.slice(0, 25)}...`
            : selectedAsset?.name;

    const handleAddToDesign = async () => {
        try {
            if (!selectedAsset) {
                setError("No asset selected.");
                return;
            }

            let assetUrl = selectedAsset.preview || selectedAsset.thumbnail || selectedAsset.url;

            // Ensure we have a full URL (handle relative paths)
            if (assetUrl && !assetUrl.startsWith("http")) {
                assetUrl = `https://${user_name}.filerobot.com${assetUrl}`;
            }

            if (!assetUrl) {
                setError("No valid asset source found.");
                return;
            }

            try {
                // Handle DOCX separately
                const ext = selectedAsset.file_ext?.toLowerCase();

                if (ext === "doc" || ext === "docx" || ext === "pdf") {
                    await insertDocxIntoSlide(assetUrl);
                    console.log(`${ext.toUpperCase()} successfully inserted as attachment into slide.`);
                    return;
                }

                // Handle normal images & SVGs
                const base64String = await urlToBase64(assetUrl);
                const cleanBase64 = base64String.split(',')[1];

                if (selectedAsset.file_ext?.toLowerCase() === "svg") {
                    await insertSvgIntoSlide(cleanBase64);
                } else {
                    await insertImgIntoSlide(cleanBase64);
                }

                console.log("Asset successfully inserted into slide.");
            } catch (insertError) {
                setError("Failed to insert asset into slide. Please try again.");
                console.error("Insert error:", insertError);
            }
        } catch (conversionError) {
            setError("Error processing the asset. Please try again.");
            console.error("Conversion error:", conversionError);
        }
    };

    const imageSrc = selectedAsset?.url?.startsWith("http") &&
        selectedAsset.url ||
        selectedAsset?.preview ||
        selectedAsset?.thumbnail;

    return (
        <>
            <Header />

            {/* Back Button & Title (always visible) */}
            <Stack direction="row" alignItems="center" spacing={1} sx={{ margin: "12px 6px" }}>
                <IconButton
                    sx={{
                        padding: "6px",
                        "&:hover": { backgroundColor: "#f3f4f6", borderRadius: "12px" },
                    }}
                    onClick={handleBackToAssets}
                >
                    <FiArrowLeft size={20} />
                </IconButton>
                <Typography sx={{ color: "#000", fontSize: "16px", fontWeight: 600 }}>
                    {displayName}
                </Typography>
            </Stack>

            {/* Loader vs Content */}
            {isImageLoading ? (
                <ImgLoading />
            ) : (
                <>
                    {/* Action Button */}
                    <Stack sx={{ margin: "12px 12px" }}>
                        <Button
                            variant="contained"
                            sx={{
                                color: "#fff",
                                fontWeight: 600,
                                textTransform: "none",
                                marginTop: "8px",
                            }}
                            onClick={handleAddToDesign}
                        >
                            {UIText.tabs.assets_view.assets_details.add_to_design}
                        </Button>
                    </Stack>

                    {/* Asset Preview */}
                    <Box sx={{ display: "flex", justifyContent: "center", mt: 2 }}>
                        {imageSrc ? (
                            selectedAsset?.file_ext?.toLowerCase() === "mp4" ||
                                selectedAsset?.type?.startsWith("video/") ? (
                                <Box
                                    component="video"
                                    src={imageSrc}
                                    controls
                                    autoPlay={false}
                                    sx={{
                                        maxWidth: "92.2%",
                                        maxHeight: "80vh",
                                        borderRadius: 2,
                                        boxShadow: 2,
                                        backgroundColor: "#000",
                                    }}
                                    onLoadedData={() => setIsImageLoading(false)}
                                    onError={() => {
                                        setIsImageLoading(false);
                                        setError(UIText.tabs.assets_view.assets_details.not_found);
                                    }}
                                />
                            ) : selectedAsset?.file_ext?.toLowerCase() === "docx" ||
                                selectedAsset?.file_ext?.toLowerCase() === "doc" ? (
                                <Box
                                    component="img"
                                    src={`${process.env.PORD_URL}${DOCX_PREVIEW}`}
                                    alt="docx file"
                                    sx={{
                                        height: "214px",
                                        borderRadius: 2,
                                        boxShadow: 2,
                                    }}
                                    onLoad={() => setIsImageLoading(false)}
                                />
                            ) : selectedAsset?.file_ext?.toLowerCase() === "pdf" ? (
                                <Box
                                    component="img"
                                    src={`${process.env.PORD_URL}${PDF_PREVIEW}`}
                                    alt="pdf file"
                                    sx={{
                                        height: "214px",
                                        borderRadius: 2,
                                        boxShadow: 2,
                                    }}
                                    onLoad={() => setIsImageLoading(false)}
                                />
                            ) : (selectedAsset?.type?.startsWith("image/") ||
                                ["png", "jpg", "jpeg", "gif", "webp", "bmp", "tiff", "ai"].includes(selectedAsset?.file_ext?.toLowerCase() || "")
                            ) ? (
                                <Box
                                    component="img"
                                    src={imageSrc}
                                    alt={selectedAsset?.name}
                                    sx={{
                                        maxWidth: "92.2%",
                                        maxHeight: "80vh",
                                        borderRadius: 2,
                                        boxShadow: 2,
                                    }}
                                    onLoad={() => setIsImageLoading(false)}
                                    onError={() => {
                                        setIsImageLoading(false);
                                        setError(UIText.tabs.assets_view.assets_details.not_found);
                                    }}
                                />
                            ) : (
                                // Default Preview (url exists but unsupported type)
                                <Box
                                    component="img"
                                    src={`${process.env.PORD_URL}${DEFAULT_PREVIEW}`}
                                    alt="default preview"
                                    sx={{
                                        height: "214px",
                                        borderRadius: 2,
                                        boxShadow: 2,
                                    }}
                                    onLoad={() => setIsImageLoading(false)}
                                />
                            )
                        ) : (
                            // No URL at all (show NotFound)
                            <NotFound />
                        )}
                    </Box>

                    {/* Asset Info */}
                    <Typography sx={{ color: "#1e1e1eff", fontSize: "14px", padding: "12px 0 0 16px" }}>
                        {`Name: ${displayName}` || '—'}
                    </Typography>
                    <Typography sx={{ color: "#1e1e1eff", fontSize: "14px", padding: "4px 0 0 16px" }}>
                        {`Dimension: ${selectedAsset?.img_w} x ${selectedAsset?.img_h}` || '—'}
                    </Typography>
                    <Typography sx={{ color: "#1e1e1eff", fontSize: "14px", padding: "4px 0 0 16px" }}>
                        {`Type: ${selectedAsset?.type}` || '—'}
                    </Typography>
                    <Typography sx={{ color: "#1e1e1eff", fontSize: "14px", padding: "4px 0 12px 16px" }}>
                        {`Size: ${selectedAsset?.size}` || '—'}
                    </Typography>
                </>
            )}

            {/* Hidden image (ensures onLoad fires even while showing skeleton) */}
            {imageSrc && (
                <Box
                    component="img"
                    src={imageSrc}
                    alt="preload"
                    sx={{ display: "none" }}
                    onLoad={() => setIsImageLoading(false)}
                    onError={() => setIsImageLoading(false)}
                />
            )}

            {/* Error Toast */}
            {error && <Toast error={error} />}
        </>
    );
};

export default AssetDetails;
