import React, { createContext, useContext, useState } from "react";
import { DataContextTypeProps, FolderCacheType } from "../utilities/types";
import { } from "../utilities/types";
import { sort_by } from "../utilities/allData";

const DataContext = createContext<DataContextTypeProps>(undefined);

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [allFolders, setAllFolders] = useState<any[]>([]);
  const [allAssetUrls, setAllAssetUrls] = useState<string[]>([]);
  const [allAssetDetails, setAllAssetDetails] = useState<any[]>([]);
  const [allRootDirAssetDetails, setAllRootDirAssetDetails] = useState<any[]>([]);
  const [allSubFoldersNames, setAllSubFoldersNames] = useState<any[]>([]);
  const [folderCache, setFolderCache] = useState<FolderCacheType>({});
  const [sortValue, setSortValue] = useState<string>(sort_by[0].toLowerCase());
  const [isLoading, setIsLoading] = useState<Boolean>(false);
  const [companies, setCompanies] = useState<any[]>([]);

  return (
    <DataContext.Provider
      value={{
        allFolders,
        setAllFolders,
        allAssetUrls,
        setAllAssetUrls,
        allAssetDetails,
        setAllAssetDetails,
        allRootDirAssetDetails,
        setAllRootDirAssetDetails,
        allSubFoldersNames,
        setAllSubFoldersNames,
        folderCache,
        setFolderCache,
        isLoading,
        setIsLoading,
        sortValue,
        setSortValue,
        companies,
        setCompanies
      }}
    >
      {children}
    </DataContext.Provider>
  );
};

export const useData = (): DataContextTypeProps => {
  const ctx = useContext(DataContext);
  if (!ctx) throw new Error("useData must be used inside DataProvider");
  return ctx;
};
