const getFolderContents = async (x_filerobot_key: string, user_name: string, folderName: string) => {
  const encodedFolder = encodeURIComponent(`/${folderName.replace(/^\/+/, '')}`);
  const headers = { "X-Filerobot-Key": x_filerobot_key };

  const [foldersRes, filesRes] = await Promise.all([
    fetch(`${process.env.API_BASE_URL}/${user_name}/v5/folders?folder=${encodedFolder}&recursive=0`, { headers }),
    fetch(`${process.env.API_BASE_URL}/${user_name}/v5/files?folder=${encodedFolder}&sort=name:asc&offset=0&limit=1000&recursive=0`, { headers })
  ]);

  const foldersJson = await foldersRes.json();
  const filesJson = await filesRes.json();

  console.log("Folders:", foldersJson);
  console.log("Files:", filesJson);

  return {
    folders: foldersJson.folders || [],
    files: filesJson.files || [],
  };
}

export default getFolderContents;