import React from "react";
import { Box, Stack, Skeleton } from "@mui/material";

const Loading = () => {
    return (
        <>
            <Box>
                <Stack spacing={2}>
                    {/* Top bar skeleton (tabs/buttons) */}
                    <Stack direction="row" spacing={2}>
                        <Skeleton variant="rounded" width={60} height={20} />
                        <Skeleton variant="rounded" width={60} height={20} />
                        <Skeleton variant="rounded" width={60} height={20} />
                    </Stack>

                    <Skeleton variant="rounded" height={6} width="40%" />

                    {/* Large title bar */}
                    <Skeleton variant="rounded" height={20} width="100%" />

                    {/* List items */}
                    {[1, 2, 3].map((item) => (
                        <Stack key={item} direction="row" spacing={1} alignItems="center">
                            <Skeleton width={50} height={80} />
                            <Stack spacing={1} sx={{ flex: 1 }}>
                                <Skeleton variant="rounded" width="100%" height={16} />
                                <Skeleton variant="rounded" width="100%" height={6} />
                            </Stack>
                        </Stack>
                    ))}

                    {/* Footer bar */}
                    <Skeleton variant="rounded" height={14} width="90%" />

                    {/* Two equal cards */}
                    <Stack direction="row" spacing={2}>
                        <Box sx={{ flex: 1 }}>
                            <Skeleton variant="rounded" width="100%" height={120} />
                        </Box>
                        <Box sx={{ flex: 1 }}>
                            <Skeleton variant="rounded" width="100%" height={120} />
                        </Box>
                    </Stack>
                </Stack>
            </Box>
        </>
    );
}

export default Loading;