import React, { useState, ChangeEvent, useRef, useEffect } from 'react';
import { Dialog, DialogContent, Box, Typography, Button, Link } from '@mui/material';
import { FiShield } from 'react-icons/fi';
import Loader from '../../loader/loader';
import Toast from '../../toast/Toast';
import { useNavigate } from 'react-router-dom';
import { getMFACode } from '../../../auth/getMFACode';

const TIMER_START = 59;

const VerificationDialog: React.FC<{ mfa_uuid: string }> = ({ mfa_uuid }) => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [MFACode, setMFACode] = useState<string>('');
    const [info, setInfo] = useState('');
    const [error, setError] = useState('');
    const [timer, setTimer] = useState(TIMER_START);
    const timerRef = useRef<NodeJS.Timeout | null>(null);

    // Start timer on mount
    useEffect(() => {
        if (timerRef.current) clearInterval(timerRef.current);
        setTimer(TIMER_START);
        timerRef.current = setInterval(() => {
            setTimer(prev => {
                if (prev <= 1) {
                    if (timerRef.current) clearInterval(timerRef.current);
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    // Only allow numeric input, max 6 digits
    const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
        let value = e.target.value.replace(/\D/g, '');
        if (value.length > 6) value = value.slice(0, 6);
        setMFACode(value);
    };

    // Call handle verify mfa code click
    const handleVerifyMFACode = (isResend = false) => {
        if (isResend) {
            setInfo('A new code has been sent.');
            setError('');
            setMFACode('');
            setTimer(TIMER_START);
            if (timerRef.current) clearInterval(timerRef.current);
            timerRef.current = setInterval(() => {
                setTimer(prev => {
                    if (prev <= 1) {
                        if (timerRef.current) clearInterval(timerRef.current);
                        return 0;
                    }
                    return prev - 1;
                });
            }, 1000);
            return;
        }
        if (MFACode.length === 6 && mfa_uuid) {
            setIsLoading(true);
            setInfo('');
            setError('');
            getMFACode(MFACode, mfa_uuid, async (error, data) => {
                if (error) {
                    setError((error as any).msg);
                    console.log((error as any).msg);
                    setIsLoading(false);
                } else if (data) {
                    console.log(data);
                    localStorage.setItem("session_uuid", data.session_uuid);
                    localStorage.setItem("expires_x_session_token", data.api_info.timestamp);

                    navigate(data.redirect_to)
                    setIsLoading(false);
                    setTimer(TIMER_START); // After success, show timer and 'Didn't get a code?'
                    setMFACode('');
                }
            });
        } else {
            setInfo('Please enter a valid 6-digit MFA code');
        }
    };

    return (
        <>
            <Dialog open fullWidth maxWidth="xs" PaperProps={{ style: { borderRadius: "16px" } }}>
                <DialogContent sx={{ p: "12px", textAlign: 'center', position: 'relative', background: '#fff' }}>
                    <Box display="flex" justifyContent="center" mb={1}>
                        <Box sx={{ background: '#e0e7ff', borderRadius: '50%', display: "flex", alignItems: "center", justifyContent: "center", p: 1.5 }}>
                            <FiShield style={{ color: '#2563eb', fontSize: 22 }} />
                        </Box>
                    </Box>
                    <Typography fontWeight={600} fontSize={20}>
                        Verify it’s you
                    </Typography>
                    <Typography fontSize={12} color="#5f5f5f" mb={2}>
                        We’ve sent a verification code to you.
                        Enter the recieved code in the field below.
                    </Typography>
                    <Box mb={2} textAlign="left">
                        <Box
                            sx={{
                                display: 'flex',
                                alignItems: 'center',
                                border: '1px solid #d1d5db',
                                borderRadius: 2,
                                py: 1.2,
                                background: '#fff',
                                width: '99%',
                            }}
                        >
                            <Typography fontSize={16} color="#6b7280" fontWeight={400} sx={{ minWidth: 60, paddingLeft: "4px" }}>
                                MFA —
                            </Typography>
                            <input
                                type="text"
                                inputMode="numeric"
                                pattern="[0-9]*"
                                value={MFACode}
                                onChange={handleChange}
                                maxLength={6}
                                style={{
                                    border: 'none',
                                    outline: 'none',
                                    background: 'transparent',
                                    fontSize: 18,
                                    fontWeight: 600,
                                    letterSpacing: '4px',
                                    width: '160px',
                                    textAlign: 'left',
                                    color: '#222',
                                    padding: 0,
                                }}
                            />
                        </Box>
                    </Box>
                    <Button
                        variant="contained"
                        disabled={MFACode.length !== 6 || isLoading}
                        fullWidth
                        sx={{
                            bgcolor: MFACode.length === 6 && !isLoading ? '#1976D2' : '#e0e0e0',
                            color: MFACode.length === 6 && !isLoading ? '#fff' : '#a3a3a3',
                            fontWeight: 600,
                            fontSize: 16,
                            py: 1,
                            borderRadius: 2,
                            boxShadow: 'none',
                            textTransform: 'none',
                            position: 'relative',
                            '&:hover': { bgcolor: MFACode.length === 6 && !isLoading ? '#1976D2' : '#e0e0e0' }
                        }}
                        onClick={() => handleVerifyMFACode(false)}
                    >
                        {isLoading ? (
                            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', width: '100%' }}>
                                <Loader loader={{ size: "20px", color: "white" }} loaderOverlay={undefined} />
                            </Box>
                        ) : (
                            'Verify'
                        )}
                    </Button>

                    {/* Message logic */}
                    {timer > 0 ? (
                        <Typography fontSize={12} color="#6b7280" mt={2}>
                            Send code one more time?
                            <span style={{ color: '#2563eb', fontWeight: 600 }}> {timer < 10 ? `00:0${timer}` : `00:${timer}`} </span>
                        </Typography>
                    ) : (
                        <Typography fontSize={12} color="#6b7280" mt={2}>
                            Didn't get a code?
                            <Link
                                component="button"
                                underline="hover"
                                sx={{ color: '#2563eb', fontWeight: 600, cursor: 'pointer', ml: 0.5 }}
                                onClick={() => handleVerifyMFACode(true)}
                            >
                                Resend
                            </Link>
                        </Typography>
                    )}
                </DialogContent>
            </Dialog>

            {info && (<Toast info={info} />)}
            {error && (<Toast error={error} />)}
        </>
    );
};

export default VerificationDialog;