import React, { useEffect, useState } from "react";
import { Box, Button, Checkbox, List, ListItem, ListItemButton, ListItemText, Menu, MenuItem, TextField, Typography, } from "@mui/material";
import { FilterDropdownProps } from "../../../utilities/types";
import FolderSelectionDialog from "./folderSelectionDialog";

const FilterDropdown: React.FC<FilterDropdownProps> = ({ filterDropDown, onClose }) => {
    const [selectedFolder, setSelectedFolder] = useState<string>("All folders");
    const [folderSelectedOnce, setFolderSelectedOnce] = useState<boolean>(false);
    const [showDialog, setShowDialog] = useState<boolean>(false);
    const [dialogValue, setDialogValue] = useState<string>("");

    const [formatFilters, setFormatFilters] = useState({
        VIDEO: false,
        AUDIO: false,
        PNG: false,
        JPEG: false,
        SVG: false,
        WEBP: false,
        GIF: false,
    });

    const [fileType, setFileType] = useState({
        Image: false,
        Video: false,
        Audio: false,
        Document: false,
    });

    const folders = [
        "All folders",
        "O_test_perf",
        "local",
        "MS365",
        "plugins_assets",
        "Sample Images",
    ];

    // Load saved state
    useEffect(() => {
        const storedFolder = localStorage.getItem("filterSelectedFolder");
        const storedFormat = localStorage.getItem("filterFormatFilters");
        const storedFileType = localStorage.getItem("filterFileType");
        const storedFolderOnce = localStorage.getItem("filterFolderOnce");

        if (storedFolder) setSelectedFolder(storedFolder);
        if (storedFormat) setFormatFilters(JSON.parse(storedFormat));
        if (storedFileType) setFileType(JSON.parse(storedFileType));
        if (storedFolderOnce === "true") setFolderSelectedOnce(true);
    }, []);

    // Save to localStorage and update filter count
    useEffect(() => {
        localStorage.setItem("filterSelectedFolder", selectedFolder);
        localStorage.setItem("filterFormatFilters", JSON.stringify(formatFilters));
        localStorage.setItem("filterFileType", JSON.stringify(fileType));
        localStorage.setItem("filterFolderOnce", folderSelectedOnce.toString());

        const totalChecked = [
            ...Object.values(formatFilters),
            ...Object.values(fileType),
        ].filter(Boolean).length;

        const folderCount = (selectedFolder !== "All folders" || folderSelectedOnce) ? 1 : 0;
        const total = totalChecked + folderCount;

        localStorage.setItem("filterCount", total.toString());
    }, [selectedFolder, formatFilters, fileType, folderSelectedOnce]);

    const handleFolderChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const folder = event.target.value;
        setSelectedFolder(folder);
        setDialogValue(folder);
        if (folder !== "All folders") {
            setShowDialog(true);
        }
    };

    const handleSelectFromDialog = () => {
        setFolderSelectedOnce(true);
        setShowDialog(false);
    };

    const handleDialogClose = () => {
        setShowDialog(false);
    };

    const handleFormatChange = (format: keyof typeof formatFilters) => {
        setFormatFilters((prev) => ({
            ...prev,
            [format]: !prev[format],
        }));
    };

    const handleFileTypeChange = (type: keyof typeof fileType) => {
        setFileType((prev) => ({
            ...prev,
            [type]: !prev[type],
        }));
    };

    const clearAll = () => {
        setSelectedFolder("All folders");
        setFolderSelectedOnce(false);
        setFormatFilters({
            VIDEO: false,
            AUDIO: false,
            PNG: false,
            JPEG: false,
            SVG: false,
            WEBP: false,
            GIF: false,
        });
        setFileType({
            Image: false,
            Video: false,
            Audio: false,
            Document: false,
        });
    };

    const applyFilters = () => {
        onClose();
    };

    return (
        <>
            <Menu
                anchorEl={filterDropDown}
                open={Boolean(filterDropDown)}
                onClose={onClose}
                anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
                transformOrigin={{ vertical: "top", horizontal: "right" }}
                PaperProps={{
                    sx: {
                        width: 300,
                        display: "flex",
                        flexDirection: "column",
                        maxHeight: 360,
                        p: 0,
                    },
                }}
            >
                {/* Scrollable content */}
                <Box sx={{ p: 2, flex: 1, overflowY: "auto" }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                        All Folders
                    </Typography>
                    <TextField
                        select
                        variant="outlined"
                        size="small"
                        value={selectedFolder}
                        onChange={handleFolderChange}
                        sx={{
                            width: "100%",
                        }}
                    >
                        {folders.map((folder) => (
                            <MenuItem key={folder} value={folder}>
                                {folder}
                            </MenuItem>
                        ))}
                    </TextField>

                    {/* Format Section */}
                    <Typography variant="subtitle1" sx={{ fontWeight: 600, mt: 2 }}>
                        Format
                    </Typography>
                    <List dense sx={{ py: 0 }}>
                        {Object.keys(formatFilters).map((format) => (
                            <ListItem key={format} disablePadding sx={{ height: 32 }}>
                                <ListItemButton
                                    onClick={() =>
                                        handleFormatChange(format as keyof typeof formatFilters)
                                    }
                                    sx={{ p: 0 }}
                                >
                                    <Checkbox
                                        checked={formatFilters[format as keyof typeof formatFilters]}
                                        size="small"
                                    />
                                    <ListItemText primary={format} sx={{ ml: 1 }} />
                                </ListItemButton>
                            </ListItem>
                        ))}
                    </List>

                    {/* File Type Section */}
                    <Typography variant="subtitle1" sx={{ fontWeight: 600, mt: 2 }}>
                        File Type
                    </Typography>
                    <List dense sx={{ py: 0 }}>
                        {Object.keys(fileType).map((type) => (
                            <ListItem key={type} disablePadding sx={{ height: 32 }}>
                                <ListItemButton
                                    onClick={() =>
                                        handleFileTypeChange(type as keyof typeof fileType)
                                    }
                                    sx={{ p: 0 }}
                                >
                                    <Checkbox
                                        checked={fileType[type as keyof typeof fileType]}
                                        size="small"
                                    />
                                    <ListItemText primary={type} sx={{ ml: 1 }} />
                                </ListItemButton>
                            </ListItem>
                        ))}
                    </List>
                </Box>

                {/* Fixed bottom buttons */}
                <Box
                    sx={{
                        display: "flex",
                        gap: 1,
                        px: 2,
                        py: 1.5,
                        borderTop: "1px solid #eee",
                        backgroundColor: "white",
                        position: "sticky",
                        bottom: 0,
                        zIndex: 1,
                    }}
                >
                    <Button
                        variant="outlined"
                        fullWidth
                        onClick={clearAll}
                        sx={{
                            textTransform: "none",
                            color: 'text.secondary',
                            borderColor: 'divider',
                        }}
                    >
                        Clear all
                    </Button>
                    <Button
                        variant="contained"
                        fullWidth
                        onClick={applyFilters}
                    >
                        Apply
                    </Button>
                </Box>
            </Menu>

            {/* Folder Dialog */}
            <FolderSelectionDialog
                open={showDialog}
                dialogValue={dialogValue}
                onClose={handleDialogClose}
                onSelect={handleSelectFromDialog}
            />
        </>
    );
};

export default FilterDropdown;