/* eslint-disable prettier/prettier */
import React from "react";
import { MemoryRouter as Router, Routes, Route } from "react-router-dom";
import Login from "../components/pages/login/page";
import EmailPassword from "../components/pages/login/emailpassword";
import Home from "../components/pages/home/page";
import Setting from "../components/pages/setting/page";
import FoldersAssets from "../components/pages/tabs/folders/foldersAssets";
import AssetDetails from "../components/pages/tabs/assets/assetDetails";

const RouterApp: React.FC = () => {
    return (
        <Router>
            <Routes>
                <Route path="/" element={<Login />} />
                <Route path="/email-password" element={<EmailPassword />} />
                <Route path="/dashboard" element={<Home />} />
                <Route path="/settings" element={<Setting />} />
                <Route path="/folders-assets" element={<FoldersAssets />} />
                <Route path="/asset-details" element={<AssetDetails />} />
            </Routes>
        </Router>
    )
}

export default RouterApp;
