export const getProjectToken = async (x_company_token: string, x_session_token: string, callback: (error: Error | null, data: any | null) => void): Promise<void> => {
    const myHeaders = new Headers();
    myHeaders.append("X-Company-Token", x_company_token);
    myHeaders.append("X-Session-Token", x_session_token);

    const requestOptions = {
        method: "GET",
        headers: myHeaders
    };

    fetch(`${process.env.AUTH_BASE_URL}/api/projects`, requestOptions)
        .then((response) => response.json())
        .then((result) => {
            if (result.status === "success") {
                console.log(result);
                localStorage.setItem("x-project-token", result.projects[0].uuid);
                localStorage.setItem("userToken", result.projects[0].name);

                callback(null, result);
            } else {
                callback(result, null);
            }
        })
        .catch((error) => {
            console.error(error);
            callback(error, null);
        });
}