import React from 'react';
import { Dialog, Box, IconButton, Typography, Button } from '@mui/material';
import { FolderSelectionDialogProps } from '../../../utilities/types';
import { IoArrowBack } from 'react-icons/io5';

const FolderSelectionDialog: React.FC<FolderSelectionDialogProps> = ({ open, dialogValue, onClose, onSelect }) => {
    return (
        <>
            <Dialog open={open} onClose={onClose} fullWidth maxWidth="xs">
                <Box sx={{ p: 2 }}>
                    <Box sx={{ display: "flex", alignItems: "center", mb: 2 }}>
                        <IconButton onClick={onClose} size="small">
                            <IoArrowBack />
                        </IconButton>
                        <Typography sx={{ fontWeight: 600, ml: 1 }}>
                            {dialogValue}
                        </Typography>
                    </Box>

                    <Typography sx={{ mb: 3, fontSize: 14, color: 'text.secondary', textAlign: 'center' }}>
                        Filter results from this folder
                    </Typography>

                    <Button
                        variant="contained"
                        fullWidth
                        onClick={onSelect}
                        sx={{
                            textTransform: "none",
                        }}
                    >
                        Select
                    </Button>
                </Box>
            </Dialog>
        </>
    );
};

export default FolderSelectionDialog;