import React, { useState, useEffect } from "react";
import { Dialog, DialogTitle, DialogContent, Typography, DialogActions, Button, Autocomplete, TextField, } from "@mui/material";
import { Company, TokenAccessDialogProps } from "../../../utilities/types";

const TokenAccessDialog: React.FC<TokenAccessDialogProps> = ({ open, email, companies, onClose, onLoginAnotherAccount, onConfirm, }) => {
    const [selectedCompany, setSelectedCompany] = useState<Company | null>(null);

    // reset selection when companies change
    useEffect(() => {
        if (companies && companies.length > 0) {
            // default to first company passed in
            setSelectedCompany(companies[0]);
        }
    }, [companies]);

    const handleConfirm = () => {
        if (selectedCompany) {
            onConfirm([selectedCompany]);
        }
    };

    return (
        <>
            <Dialog
                open={open}
                onClose={onClose}
                PaperProps={{
                    sx: { borderRadius: "12px", minWidth: "300px" },
                }}
            >
                {/* Title */}
                <DialogTitle
                    sx={{ textAlign: "center", fontWeight: "bold", fontSize: "20px" }}
                >
                    Access approved
                </DialogTitle>

                {/* Content */}
                <DialogContent sx={{ textAlign: "center" }}>
                    <Typography sx={{ fontSize: "14px", color: "#5F5F5F", mb: 2 }}>
                        With access to your <b>{email}</b> account, MS365 can use all protected Hub APIs.
                    </Typography>

                    {/* Autocomplete Dropdown */}
                    <Autocomplete
                        size="small"
                        fullWidth
                        value={selectedCompany}
                        onChange={(_, newValue) => setSelectedCompany(newValue)}
                        options={companies}
                        getOptionLabel={(option) => option.name || ""}
                        isOptionEqualToValue={(option, value) => option.id === value.id} // :key: ensures correct match
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                label="Project"
                                placeholder="Search a company or project"
                            />
                        )}
                    />
                </DialogContent>

                {/* Actions */}
                <DialogActions
                    sx={{
                        display: "flex",
                        justifyContent: "center",
                        alignItems: "center",
                        flexDirection: "column",
                        px: 3,
                        pb: 2,
                        gap: 1,
                    }}
                >
                    <Button
                        variant="contained"
                        sx={{ textTransform: "capitalize", fontWeight: 600 }}
                        onClick={handleConfirm}
                        fullWidth
                    >
                        Grant access
                    </Button>
                    <Button
                        variant="outlined"
                        sx={{
                            textTransform: "capitalize",
                            borderColor: "#ccc",
                            color: "#333",
                            fontWeight: 500,
                            backgroundColor: "#F9F9F9"
                        }}
                        onClick={onLoginAnotherAccount}
                        fullWidth
                    >
                        Login with another account
                    </Button>
                    <Button
                        variant="outlined"
                        sx={{ textTransform: "capitalize" }}
                        onClick={onClose}
                        fullWidth
                    >
                        Deny access
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    );
};

export default TokenAccessDialog;