import React, { useState } from 'react';
import { Box, TextField, InputAdornment, IconButton, MenuItem as MuiMenuItem } from '@mui/material';
import { IoSearchOutline } from "react-icons/io5";
import { LuArrowDownUp } from "react-icons/lu";
import { RiEqualizerLine } from "react-icons/ri";
import FilterDropdown from './filterDropdown';
import { sort_by, sortMap } from '../../../utilities/allData';
import { getAssetsSortBy, getFoldersSortBy, getSubFoldersSortBy } from '../../../services/sortBy';
import { AssetDetail, SearchProps } from '../../../utilities/types';
import Loading from '../../loader/loading';
import { useData } from '../../../hook/DataContext';

const Search: React.FC<SearchProps> = ({ pageName, displayName, onAssetsChange, onFoldersChange }) => {
    const [filterDropDown, setFilterDropDown] = useState<null | HTMLElement>(null);
    const filterCount = parseInt(localStorage.getItem("filterCount") || "0", 10);
    const user_name = localStorage.getItem("user-name");
    const X_SAAS_Key = localStorage.getItem("X_SAAS_Key");

    const { setAllAssetDetails, setAllFolders, setAllSubFoldersNames, sortValue, setSortValue, isLoading, setIsLoading } = useData();

    const handleOpenFilterDropdown = (event: React.MouseEvent<HTMLElement>) => {
        setFilterDropDown(event.currentTarget);
    };

    const handleClose = () => setFilterDropDown(null);

    /* Normalize file object into AssetDetail */
    const normalizeFile = (file: any): AssetDetail => {
        const publicUrl = file.url?.public || file.url?.cdn || file.url?.path || '';
        const thumbnail = file.info?.thumbnail ?? file.info?.video_gif ?? file.info?.video_thumbnail ?? publicUrl;

        return {
            name: file.name,
            file_ext: file.info?.file_ext,
            uuid: file.uuid,
            size: file.size?.pretty,
            type: file?.type,
            img_h: file.info?.img_h,
            img_w: file.info?.img_w,
            preview: file.info?.preview,
            thumbnail,
            url: file.url?.path || publicUrl || '',
        };
    };

    const handleSortChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
        try {
            setIsLoading(true);
            const selected = event.target.value;
            setSortValue(selected.toLowerCase());

            const sortConfig = sortMap[selected];
            if (!sortConfig) throw new Error(`Unknown sort value: ${selected}`);

            const { field, direction } = sortConfig;

            if (X_SAAS_Key && user_name) {
                console.log("Sorting assets for:", displayName);

                // Assets
                const assetsData = await new Promise<any>((resolve, reject) => {
                    getAssetsSortBy(X_SAAS_Key, user_name, pageName, displayName, field, direction, 0, 100,
                        (error, data) => error ? reject(error) : resolve(data)
                    );
                });

                if (assetsData?.files) {
                    const urls = assetsData.files
                        .map((file: any) =>
                            file.info?.thumbnail ||
                            file.info?.video_thumbnail ||
                            file.url?.cdn ||
                            file.url?.public
                        )
                        .filter(Boolean);

                    const fileDetails = assetsData.files.map(normalizeFile);

                    onAssetsChange(urls);
                    if (displayName === "dashboard") {
                        setAllAssetDetails(fileDetails);
                    }
                }

                // Folders
                const foldersData = await new Promise<any>((resolve, reject) => {
                    getFoldersSortBy(X_SAAS_Key, user_name, field, direction,
                        (error, data) => error ? reject(error) : resolve(data)
                    );
                });

                if (foldersData?.folders) {
                    setAllFolders(foldersData.folders);
                    console.log("Folders updated:", foldersData.folders);
                }

                // SubFolders
                if (displayName && displayName !== "dashboard") {
                    getSubFoldersSortBy(X_SAAS_Key, user_name, displayName, field, direction, 0,
                        (error, data) => {
                            if (error) {
                                console.error("Error fetching subfolders:", error);
                                return;
                            }
                            if (data?.folders) {
                                const subFolders = data.folders.map((folder: any) => ({
                                    name: folder.name,
                                    count: {
                                        files_direct: folder.count.files_direct,
                                        files_recursive: folder.count.files_recursive,
                                    },
                                }));
                                setAllSubFoldersNames(subFolders);
                                onFoldersChange(subFolders);
                                console.log("Subfolders updated:", subFolders);
                            }
                        }
                    );
                }
            }
        } catch (err) {
            console.error("Error in handleSortChange:", err);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, m: "16px 6px 6px 6px" }}>
                {/* Search Input */}
                <TextField
                    variant="outlined"
                    placeholder="Search from Scaleflex DAM"
                    size="small"
                    InputProps={{
                        startAdornment: (
                            <InputAdornment position="start">
                                <IoSearchOutline />
                            </InputAdornment>
                        ),
                        endAdornment: (
                            <InputAdornment position="end">
                                {filterCount > 0 && (
                                    <Box
                                        sx={{
                                            height: 16,
                                            width: 16,
                                            display: "flex",
                                            justifyContent: "center",
                                            alignItems: "center",
                                            color: "#fff",
                                            fontSize: 10,
                                            borderRadius: "50%",
                                            mr: "-34px",
                                            mt: "-20px",
                                            zIndex: 20,
                                            backgroundColor: "#1976D2",
                                        }}
                                    >
                                        {filterCount}
                                    </Box>
                                )}
                                <IconButton edge="end" onClick={handleOpenFilterDropdown}>
                                    <RiEqualizerLine fontSize={18} />
                                </IconButton>
                            </InputAdornment>
                        ),
                    }}
                    sx={{ width: "100%", maxWidth: 600, zIndex: 10 }}
                />

                {/* Filter Dropdown */}
                <FilterDropdown filterDropDown={filterDropDown} onClose={handleClose} />

                {/* Sort Select */}
                <TextField
                    select
                    variant="outlined"
                    size="small"
                    value={sortValue}
                    onChange={handleSortChange}
                    placeholder="Sort by"
                    InputProps={{
                        startAdornment: (
                            <InputAdornment position="start">
                                <LuArrowDownUp />
                            </InputAdornment>
                        ),
                    }}
                    sx={{ width: "100%", maxWidth: 600 }}
                >
                    {sort_by.map((option, index) => (
                        <MuiMenuItem key={option} value={option.toLowerCase()} disabled={index === 0}>
                            {option}
                        </MuiMenuItem>
                    ))}
                </TextField>
            </Box>

            {isLoading && (
                <Box sx={{ m: 1 }}>
                    <Loading />
                </Box>
            )}
        </>
    );
};

export default Search;
